interface EventsTabProps {
	/**
	 * Org id when workspace is resolved. `null` during the cold-cache
	 * workspace-loading window (org-wide events landing only). When null,
	 * the filter-bar chrome still renders so the user sees the search +
	 * tabs from the first frame; the data queries stay disabled until
	 * workspace lands.
	 */
	organizationId: string | null;
	ownerSlug?: string; // Required for org-wide mode drill-down links
	entityId?: number; // Scope via prop (legacy) or the ?entity_id= URL filter
	/** Memory page filters sources in the sidebar rail. */
	hideSourceFilter?: boolean;
	/** Memory browse drill-down: force event queries to this entity type. */
	scopedEntityTypes?: string[];
}

interface ClassifierEntry {
	slug: string;
	name: string;
	values: string[];
	parentSlug: string | null;
	valuesByParentValue: Record<string, string[]>;
}

interface BehaviorClassifierGroup {
	behaviorName: string | null;
	classifiers: ClassifierEntry[];
}

/**
 * One node on the vertical timeline rail. The left gutter holds the dot and a
 * relative timestamp (absolute on hover); a connecting line runs the full
 * height and is hidden on the last row via `isLast` so the rail doesn't dangle
 * past the final event. Content (the borderless EventCard) sits on the right.
 */
function TimelineRow({
	occurredAt,
	isLast,
	children,
}: {
	occurredAt: string | Date | number | null | undefined;
	isLast?: boolean;
	children: React.ReactNode;
}) {
	return (
		<div className="relative flex gap-4 pb-6">
			{/* Rail: dot + connecting line. The line spans the full row height so
			    adjacent nodes read as one continuous timeline; `isLast` drops it on
			    the final row so the rail doesn't dangle past the last event. */}
			<div className="relative flex w-2.5 shrink-0 justify-center">
				{!isLast && (
					<div
						className="absolute top-1 bottom-[-1.5rem] left-1/2 w-px -translate-x-1/2 bg-border"
						aria-hidden
					/>
				)}
				<div className="relative z-10 mt-1 h-2.5 w-2.5 rounded-full border-2 border-background bg-muted-foreground/60" />
			</div>

			{/* Content column: timestamp header + event body */}
			<div className="min-w-0 flex-1">
				{occurredAt && (
					<time
						dateTime={new Date(occurredAt).toISOString()}
						title={formatShortDate(occurredAt)}
						className="mb-1 block text-xs leading-none text-muted-foreground"
					>
						{formatTimeAgo(occurredAt)}
					</time>
				)}
				{children}
			</div>
		</div>
	);
}

export function EventsTab({
	organizationId,
	ownerSlug,
	entityId,
	hideSourceFilter = false,
	scopedEntityTypes,
}: EventsTabProps) {
	const { isAuthenticated, isReady } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isReady && isAuthenticated && isMember;
	const canReadPublicWorkspace =
		isReady && (!isAuthenticated || (!isOrgLoading && !isMember));

	const navigate = useNavigate();
	const location = useLocation();
	const scheduleScopeId = parseScheduleScope(location.search ?? {});

	const {
		filters: urlFilters,
		updateFilters: updateUrlFilters,
		clearFilters: clearUrlFilters,
	} = useTabFilters<PartialEventFilters>({
		parse: parseEventFiltersFromUrl,
		serialize: serializeEventFiltersToSearch,
		filterKeys: EVENT_FILTER_KEYS,
		merge: mergeEventTabFilters,
	});

	// Local search state (for debouncing)
	const [searchQuery, setSearchQuery] = useState(urlFilters.searchQuery || "");
	const debouncedSearch = useDebounce(searchQuery, 1000);

	// Combine URL filters with debounced search
	const filters = useMemo<PartialEventFilters>(
		() =>
			applyEventTabDefaults({
				...urlFilters,
				searchQuery: debouncedSearch.length >= 3 ? debouncedSearch : undefined,
				...(scopedEntityTypes?.length
					? { entityTypes: scopedEntityTypes }
					: {}),
			}),
		[urlFilters, debouncedSearch, scopedEntityTypes],
	);

	const updateFilters = updateUrlFilters;

	useEffect(() => {
		const normalizedSearch =
			debouncedSearch.length >= 3 ? debouncedSearch : undefined;
		if ((urlFilters.searchQuery || undefined) === normalizedSearch) {
			return;
		}
		updateUrlFilters({ searchQuery: normalizedSearch });
	}, [debouncedSearch, updateUrlFilters, urlFilters.searchQuery]);

	const clearFilters = () => {
		setSearchQuery("");
		clearUrlFilters();
	};

	const hasFilters = useMemo(
		() =>
			checkActiveFilters(
				applyEventTabDefaults({
					...urlFilters,
					searchQuery:
						debouncedSearch.length >= 3 ? debouncedSearch : undefined,
				}),
			),
		[urlFilters, debouncedSearch],
	);

	// Entity scope comes from either the prop (when embedded as an entity tab) or
	// the URL drill-down filter — the entity page's "See memory" deep-links into
	// the org-wide Memory page with ?entity_id=…. Both paths scope identically.
	const effectiveEntityId = entityId ?? filters.entityId ?? undefined;
	const isOrgWide = effectiveEntityId === undefined;

	// Fetch data — gate every auth/public fork on `isReady` so the bootstrap
	// window (isAuthenticated=false, isReady=false) doesn't fire the public
	// query and 404 against a private org before auth resolves.
	const { data: connectorDefinitions = [] } = useConnectorDefinitions(
		isReady && canManageWorkspace ? organizationId : null,
	);
	const { data: publicConnectorDefinitions = [] } =
		usePublicConnectorDefinitions(canReadPublicWorkspace ? ownerSlug : null);
	const effectiveConnectorDefinitions = canManageWorkspace
		? connectorDefinitions
		: publicConnectorDefinitions;

	const memoryConnectorGroups = useOptionalMemoryConnectorGroups();
	const connectionFilterIds = filters.connectionIds;
	const hasConnectionFilter = (connectionFilterIds?.length ?? 0) > 0;
	const { data: filteredConnections = [] } = useConnections(
		isReady && canManageWorkspace ? (organizationId ?? "") : "",
		{
			connectionIds: connectionFilterIds ?? undefined,
			enabled:
				!memoryConnectorGroups &&
				isReady &&
				canManageWorkspace &&
				hasConnectionFilter,
		},
	);
	const feedFilterIds = filters.feedIds;
	const hasFeedFilter = (feedFilterIds?.length ?? 0) > 0;
	const { data: workspaceFeeds = [] } = useAllFeeds(
		isReady && canManageWorkspace ? organizationId : null,
		{
			feedIds: feedFilterIds ?? undefined,
			enabled: isReady && canManageWorkspace && hasFeedFilter,
		},
	);

	const connectionLabelSources = useMemo(() => {
		if (memoryConnectorGroups) {
			return memoryConnectorGroups.groups.flatMap((group) =>
				group.connections.map((connection) => ({
					id: connection.id,
					display_name: connection.display_name,
					connector_name: group.connector_name,
					connector_key: group.connector_key,
				})),
			);
		}
		return filteredConnections;
	}, [filteredConnections, memoryConnectorGroups]);

	const connectionFilterLabel = useMemo(
		() =>
			hasConnectionFilter
				? resolveConnectionFilterLabel(
						connectionFilterIds ?? [],
						connectionLabelSources,
					)
				: null,
		[connectionFilterIds, connectionLabelSources, hasConnectionFilter],
	);

	const feedFilterLabel = useMemo(
		() =>
			hasFeedFilter
				? resolveFeedFilterLabel(feedFilterIds ?? [], workspaceFeeds)
				: null,
		[feedFilterIds, hasFeedFilter, workspaceFeeds],
	);

	const agentFilterId = filters.agentId;
	const { data: workspaceAgents = [] } = useAgents({
		enabled: isReady && !!agentFilterId,
	});
	const agentFilterLabel = useMemo(() => {
		if (!agentFilterId || filters.watcherId != null || scheduleScopeId) {
			return null;
		}
		if ((filters.platforms?.length ?? 0) > 0) return null;
		const agent = workspaceAgents.find((item) => item.agentId === agentFilterId);
		return agent ? `From agent ${agent.name}` : `From agent ${agentFilterId}`;
	}, [
		agentFilterId,
		filters.platforms,
		filters.watcherId,
		scheduleScopeId,
		workspaceAgents,
	]);

	const watcherFilterId = filters.watcherId;
	const { data: scopedWatchers = [] } = useAgentWatchersList(agentFilterId ?? undefined, {
		includeDetails: false,
	});
	const watcherFilterLabel = useMemo(() => {
		if (watcherFilterId == null) return null;
		const match = scopedWatchers.find(
			(w) => String(w.behavior_id) === String(watcherFilterId),
		);
		return match
			? `From watch “${match.name}”`
			: `From Behavior #${watcherFilterId}`;
	}, [scopedWatchers, watcherFilterId]);

	const { data: scopedSchedules = [] } = useSchedules(agentFilterId ?? undefined);
	const scheduleFilterLabel = useMemo(() => {
		if (!scheduleScopeId || !agentFilterId) return null;
		const match = scopedSchedules.find((s) => s.id === scheduleScopeId);
		return match?.description?.trim()
			? `From schedule “${match.description.trim()}”`
			: "From scheduled task";
	}, [agentFilterId, scheduleScopeId, scopedSchedules]);

	const listenFilterLabel = useMemo(() => {
		if (
			!agentFilterId ||
			watcherFilterId != null ||
			scheduleScopeId ||
			(filters.platforms?.length ?? 0) === 0
		) {
			return null;
		}
		const platform = filters.platforms?.[0];
		return platform ? `From ${platform} listen` : null;
	}, [
		agentFilterId,
		filters.platforms,
		scheduleScopeId,
		watcherFilterId,
	]);

	const drillSourceLinks = useMemo(() => {
		if (!ownerSlug) return {};
		const links: Record<string, DrillSourceLink | undefined> = {};

		if (hasFeedFilter && feedFilterIds?.length === 1) {
			const feed = workspaceFeeds.find((f) => f.id === feedFilterIds[0]);
			if (feed) links.feedIds = feedSourceLink(ownerSlug, feed);
		}

		if (hasConnectionFilter && connectionFilterIds?.length === 1) {
			const connection = connectionLabelSources.find(
				(c) => c.id === connectionFilterIds[0],
			);
			if (connection?.connector_key) {
				links.connectionIds = connectionSourceLink(ownerSlug, {
					id: connection.id,
					connector_key: connection.connector_key,
				});
			}
		}

		if (
			agentFilterId &&
			watcherFilterId == null &&
			!scheduleScopeId &&
			(filters.platforms?.length ?? 0) === 0
		) {
			links.agentId = agentFeedsSourceLink(ownerSlug, agentFilterId);
		}

		if (agentFilterId && watcherFilterId != null) {
			links.watcherId = watcherSourceLink(
				ownerSlug,
				agentFilterId,
				String(watcherFilterId),
			);
		}

		if (agentFilterId && scheduleScopeId) {
			links.schedule = scheduleSourceLink(
				ownerSlug,
				agentFilterId,
				scheduleScopeId,
			);
		}

		if (listenFilterLabel && agentFilterId) {
			links.listen = agentFeedsSourceLink(ownerSlug, agentFilterId);
		}

		return links;
	}, [
		agentFilterId,
		connectionFilterIds,
		connectionLabelSources,
		feedFilterIds,
		typeof value === "number" ||
		typeof value === "boolean" ||
		typeof value === "bigint"
	) {
		return String(value);
	}
	if (Array.isArray(value)) {
		if (value.length === 0) return "";
		return value.every((item) => typeof item !== "object") ? (
			value.map((item) => String(item)).join(", ")
		) : (
			<pre className="overflow-x-auto rounded bg-muted/40 p-2 text-[11px] leading-relaxed whitespace-pre-wrap">
				{JSON.stringify(value, null, 2)}
			</pre>
		);
	}
	return (
		<pre className="overflow-x-auto rounded bg-muted/40 p-2 text-[11px] leading-relaxed whitespace-pre-wrap">
			{JSON.stringify(value, null, 2)}
		</pre>
	);
}

function getVisibleMetadataEntries(metadata: Record<string, unknown>) {
	return Object.entries(metadata)
		.filter(([, value]) => {
			if (value == null) return false;
			if (typeof value === "string") return value.trim().length > 0;
			if (Array.isArray(value)) return value.length > 0;
			if (typeof value === "object")
				return Object.keys(value as Record<string, unknown>).length > 0;
			return true;
		})
		.sort(([a], [b]) => a.localeCompare(b));
}

function ScoreBreakdown({
	breakdown,
}: {
	breakdown: ContentItem["score_breakdown"];
}) {
	if (!breakdown) return null;

	const items = [
		{ label: "Engagement", value: breakdown.engagement, max: 100 },
		{ label: "Criticality", value: breakdown.criticality, max: 100 },
		{ label: "Depth", value: breakdown.depth, max: 100 },
		{ label: "Authority", value: breakdown.authority, max: 100 },
		{ label: "Recency", value: breakdown.recency, max: 100 },
		{ label: "Quality", value: breakdown.quality, max: 100 },
	];

	return (
		<div className="space-y-2 text-sm">
			{items.map((item) => (
				<div key={item.label} className="flex items-center gap-2">
	 * originated inside an interactive descendant; only clicks on the card's own
	 * inert area count.
	 */
	const fromNestedControl = (event: React.SyntheticEvent) => {
		const target = event.target;
		if (!(target instanceof Element)) return false;
		const hit = target.closest(
			'a,button,input,select,textarea,[role="button"],[role="radio"]',
		);
		// The card itself carries role="button", so it matches its own selector —
		// compare against currentTarget or every click would be swallowed.
		return hit !== null && hit !== event.currentTarget;
	};
	const handleCardClick = (event: React.MouseEvent) => {
		if (fromNestedControl(event)) return;
		openPeek();
	};
	const handleCardKeyDown = (event: React.KeyboardEvent) => {
		if (event.key !== "Enter" && event.key !== " ") return;
		if (fromNestedControl(event)) return;
		event.preventDefault();
		openPeek();
	};
	const metadata = (content.metadata || {}) as Record<string, unknown>;

	// A watcher run's first-class change-set (what it created/updated inline). Its
	// own card — the diff is a property of the run, not the approval flow.
	if (content.semantic_type === "change_set") {
		return <RunChangeSetCard content={content} />;
	}

	const isOperationEvent =
		content.interaction_type === "approval" ||
		content.semantic_type === "operation" ||
		metadata.status != null ||
		metadata.action_key != null;

	// Action events get a dedicated approval UI
	if (isOperationEvent) {
		return <ActionApprovalCard content={content} />;
	}

	const roundedScore = Number.isFinite(content.score)
		? Math.round(content.score)
		: "-";

	const payloadType = content.payload_type || "text";
	const textContent = content.text_content || "";
	const shouldTruncate =
		(payloadType === "text" || payloadType === "markdown") &&
		textContent.length > 500;
	const displayText =
		shouldTruncate && !showFullText
			? `${textContent.slice(0, 500)}...`
			: textContent;

	// Well-known metadata fields (declared via eventKinds.metadataSchema)
	const thumbnail =
		(metadata.thumbnail_url as string | undefined) ||
		(metadata.thumbnail as string | undefined);
	const mediaUrl = metadata.media_url as string | undefined;
	const metadataEntries = getVisibleMetadataEntries(metadata);

	// Parse classifications
	const classifications = Object.entries(content.classifications || {}).flatMap(
		([slug, data]) => {
			const parsed = normalizeClassificationValues(data);
			return parsed.values.map((value) => ({
				slug,
				value,
				isManual: parsed.isManual,
			}));
		},
	);

	return (
		<div
			className={cn(
				isReply ? "border-l-2 border-l-muted pl-4" : "",
				canPeek &&
					"-mx-2 cursor-pointer rounded-lg px-2 py-1 transition-colors hover:bg-accent/40",
			)}
			{...(canPeek
				? {
						role: "button",
						tabIndex: 0,
						onClick: handleCardClick,
						onKeyDown: handleCardKeyDown,
					}
				: {})}
		>
			{/* Parent context for orphaned replies */}
			{showParentContext && content.parent_context && (
				<div className="mb-3 p-2 bg-muted/50 rounded-md text-sm">
					<div className="text-xs text-muted-foreground mb-1">Replying to:</div>
					<div className="font-medium">
						{content.parent_context.author_name}
					</div>
					<div className="text-muted-foreground line-clamp-2">
						{content.parent_context.text_content}
					</div>
				</div>
			)}

			{/* Header */}
			<div className="flex items-start justify-between gap-4 mb-2">
				<div className="flex-1 min-w-0">
					{content.title && (
						<h4 className="font-medium line-clamp-2 mb-1">{content.title}</h4>
					)}
					<div className="flex items-center gap-2 text-sm text-muted-foreground">
						{(() => {
							const source = deriveSourceLabel(content);
							// The badge duplicates the label when the label *is* the
							// connector (an event with no human author). Show the badge
							// only when it adds info beyond the label.
							const showBadge =
								!!content.platform && source !== sentenceCase(content.platform);
							return (
								<>
									{source && <span className="font-medium">{source}</span>}
									{showBadge && (
										<>
											{source && <span>·</span>}
											<Badge variant="outline" className="text-xs">
												{content.platform}
											</Badge>
										</>
									)}
								</>
							);
						})()}
					</div>
				</div>

				{/* Score */}
				<div className="flex items-center gap-2">
					{content.score_breakdown ? (
						<Popover>
							<PopoverTrigger asChild>
								<Button variant="ghost" size="sm" className="h-7 px-2">
									<span className="font-medium">{roundedScore}</span>
								</Button>
							</PopoverTrigger>
							<PopoverContent className="w-64" align="end">
								<div className="space-y-2">
									<h4 className="font-medium">Score Breakdown</h4>
									<ScoreBreakdown breakdown={content.score_breakdown} />
								</div>
							</PopoverContent>
						</Popover>
					) : (
						<Button variant="ghost" size="sm" className="h-7 px-2" disabled>
							<span className="font-medium">{roundedScore}</span>
						</Button>
					)}

					{content.source_url && (
						<Tooltip>
							<TooltipTrigger asChild>
								<Button variant="ghost" size="icon" className="h-7 w-7" asChild>
									<a
										href={content.source_url}
										target="_blank"
										rel="noopener noreferrer"
									>
										<ExternalLink className="h-3.5 w-3.5" />
									</a>
								</Button>
							</TooltipTrigger>
							<TooltipContent>View original</TooltipContent>
						</Tooltip>
					)}
				</div>
			</div>

			{/* Rating */}
			{content.rating && (
				<div className="flex items-center gap-1 mb-2">
					{[1, 2, 3, 4, 5].map((star) => (
						<Star
							key={star}
							className={`h-4 w-4 ${
								star <= Number(content.rating)
									? "fill-yellow-400 text-yellow-400"
									: "text-muted-foreground"
							}`}
						/>
					))}
				</div>
			)}

			{/* Thumbnail / media preview */}
			{thumbnail && (
				<a
					href={mediaUrl || content.source_url || "#"}
					target="_blank"
					rel="noopener noreferrer"
					className="block mb-2"
				>
					<img
						src={thumbnail}
						alt=""
						className={`rounded-md object-cover ${payloadType === "media" ? "max-h-96 w-full" : "max-h-48"}`}
						loading="lazy"
					/>
				</a>
			)}

			{/* Classification evidence excerpt */}
			{content.excerpt && (
				<div className="text-sm italic text-muted-foreground border-l-2 border-primary/40 pl-2 mb-1">
					{content.excerpt}
				</div>
			)}

			{/* Content */}
			{(() => {
				switch (payloadType) {
					case "markdown":
						if (displayText) {
							return (
								<div className="max-w-none text-sm space-y-2">
									<MarkdownText text={displayText} />
								</div>
							);
						}
						break;

					case "json_template": {
						const tmpl = content.payload_template as {
							root: JsonNode;
						} | null;
						if (tmpl?.root) {
							return (
								<JsonRenderer
									template={{ root: tmpl.root }}
									data={(content.payload_data as Record<string, unknown>) || {}}
								/>
							);
						}
						if (displayText) {
							return (
								<div className="text-sm whitespace-pre-wrap">{displayText}</div>
							);
						}
						break;
					}

					case "media":
						return (
							<div className="space-y-3">
								{!thumbnail && mediaUrl && (
									<a
										href={mediaUrl}
										target="_blank"
										rel="noopener noreferrer"
										className="text-sm text-primary hover:underline truncate block"
									>
										{mediaUrl}
									</a>
								)}
								{displayText && (
									<div className="text-sm whitespace-pre-wrap text-muted-foreground">
										{displayText}
									</div>
								)}
							</div>
						);

					case "empty":
						return (
							<div className="space-y-3">
								{metadataEntries.length > 0 ? (
									<dl className="grid gap-x-3 gap-y-2 text-sm sm:grid-cols-[minmax(140px,180px)_1fr]">
										{metadataEntries.map(([key, value]) => (
											<div key={key} className="contents">
												<dt className="text-muted-foreground">
													{sentenceCase(key)}
												</dt>
												<dd className="min-w-0 break-words font-mono text-xs sm:text-sm">
													{renderMetadataValue(value)}
												</dd>
											</div>
										))}
									</dl>
								) : (
									<p className="text-sm text-muted-foreground italic">
										No content
									</p>
								)}
							</div>
						);

					default:
						if (displayText) {
