/**
 * Connection-visibility principal for Behavior knowledge.read.
 *
 * - Interactive (human MCP / ordinary agent chat): the verified caller.
 * - Signed Behavior run (`BEHAVIOR_RUN_SOURCE`): null → Behavior.created_by,
 *   but only when the verified run identity matches `requestedBehaviorId`.
 *   Fails closed on mismatch so a worker cannot request another Behavior and
 *   inherit that author's private oauth_account feeds.
 */
export function resolveBehaviorVisibilityUserId(
  ctx: ToolContext,
  requestedBehaviorId: number
): string | null {
  if (ctx.sourceContext?.source !== BEHAVIOR_RUN_SOURCE) {
    return ctx.userId;
  }

  const fromConversation = ctx.sourceContext.conversationId
    ? parseBehaviorRunConversationId(ctx.sourceContext.conversationId)
    : null;
  const verifiedBehaviorId =
    ctx.actingWatcherId != null
      ? Number(ctx.actingWatcherId)
      : (fromConversation?.behaviorId ?? null);

  if (
    verifiedBehaviorId == null ||
    !Number.isSafeInteger(verifiedBehaviorId) ||
    verifiedBehaviorId !== Number(requestedBehaviorId)
  ) {
    throw new ToolUserError(
      'A Behavior run may only call knowledge.read for its own behavior_id.',
      403
    );
  }

  return null;
}

/**
 * Stamp `metadata.pending_proposal_count` onto every `change_set` content item,
 * counting the pending proposal runs still open for its window. The change_set
 * event is permanent, so its batch Approve/Reject buttons can't derive their
 * visibility from the event alone — a resolved window would keep showing live
 * buttons that error on click. One batched query over all present windows keeps
 * this off the per-item hot path; items with no window are left untouched.
 */
async function stampPendingProposalCounts(
  sql: ReturnType<typeof getDb>,
  organizationId: string,
  items: ContentItem[]
): Promise<void> {
  const windowIds = new Set<number>();
  for (const item of items) {
    if (item.semantic_type !== 'change_set') continue;
    const wid = (item.metadata as Record<string, unknown> | undefined)?.window_id;
    if (typeof wid === 'number') windowIds.add(wid);
  }
  if (windowIds.size === 0) return;

  const rows = await sql<{ window_id: number; pending: number }>`
    SELECT window_id, COUNT(*)::int AS pending
    FROM runs
    WHERE organization_id = ${organizationId}
      AND run_type = 'internal'
      AND approval_status = 'pending'
      AND window_id = ANY(${pgBigintArray([...windowIds])}::bigint[])
    GROUP BY window_id
  `;
  const pendingByWindow = new Map<number, number>();
  for (const r of rows) pendingByWindow.set(Number(r.window_id), Number(r.pending));

  for (const item of items) {
    if (item.semantic_type !== 'change_set') continue;
    const metadata = (item.metadata ?? {}) as Record<string, unknown>;
    const wid = metadata.window_id;
    if (typeof wid !== 'number') continue;
    item.metadata = {
      ...metadata,
      pending_proposal_count: pendingByWindow.get(wid) ?? 0,
    };
  }
}

