  sql: DbClient;
  rawContent: ContentRow[];
  organizationId: string;
  ownerSlug: string | null;
  baseUrl: string | undefined;
  excerptsMap: Map<number, string>;
}): Promise<ContentItem[]> {
  const { sql, rawContent, organizationId, ownerSlug, baseUrl, excerptsMap } = opts;

  // Batch-resolve client_name and parent_context in parallel — the two
  // queries are independent (one keys by event id, the other by origin_id)
  // and on a high-RTT DB the serial form pays the round-trip twice.
  const idsNeedingClientName = rawContent.filter((f) => !f.client_name).map((f) => f.id);
  const parentExternalIds = rawContent
    .filter(
      (f) => f.origin_parent_id && !rawContent.some((r) => r.origin_id === f.origin_parent_id)
    )
    .map((f) => f.origin_parent_id as string);
  const uniqueParentIds = [...new Set(parentExternalIds)];

  const [clientRows, parentRows] = await Promise.all([
    idsNeedingClientName.length > 0
      ? sql`
        SELECT e.id, oc.client_name
        FROM current_event_records e
        JOIN oauth_clients oc ON oc.id = e.client_id
        WHERE e.id = ANY(${`{${idsNeedingClientName.join(',')}}`}::bigint[])
          AND e.client_id IS NOT NULL
      `
      : Promise.resolve([] as Array<{ id: number; client_name: string }>),
    uniqueParentIds.length > 0
      ? sql`
        SELECT origin_id, author_name, title, payload_text, occurred_at, source_url, score
        FROM current_event_records
        WHERE origin_id = ANY(${pgTextArray(uniqueParentIds)}::text[])
          AND organization_id = ${organizationId}
        LIMIT ${uniqueParentIds.length}
      `
      : Promise.resolve([] as Array<Record<string, unknown>>),
  ]);

  const clientNameMap = new Map<number, string>();
  for (const row of clientRows) {
    clientNameMap.set(Number(row.id), String(row.client_name));
  }

  const parentContextMap = new Map<string, ContentItem['parent_context']>();
  for (const row of parentRows) {
    const text = String(row.payload_text ?? '');
    parentContextMap.set(String(row.origin_id), {
      author_name: String(row.author_name ?? ''),
      title: row.title ? String(row.title) : null,
      text_content: text.length > 200 ? `${text.slice(0, 200)}…` : text,
      occurred_at: String(row.occurred_at ?? ''),
      source_url: String(row.source_url ?? ''),
      score: Number(row.score) || 0,
    });
  }

  // Map to the canonical content item shape used across the app.
  const contentItems: ContentItem[] = rawContent.map((f) => {
    const metadata = parseJsonObject(f.metadata);
    const classifications = parseJsonObject(f.classifications);

    return {
      id: f.id,
      entity_ids: parsePgNumberArray(f.entity_ids),
      platform: f.platform,
      origin_id: f.origin_id ?? '',
      semantic_type: f.semantic_type ?? 'content',
      origin_type: f.origin_type ?? null,
      payload_type: f.payload_type ?? 'text',
      payload_text: f.payload_text ?? '',
      payload_data: parseJsonObject(f.payload_data),
      payload_template: f.payload_template ? parseJsonObject(f.payload_template) : null,
      attachments: parseRecordArray(f.attachments),
      author_name: f.author_name ?? null,
      client_name: f.client_name ?? clientNameMap.get(f.id) ?? null,
      title: f.title,
      text_content: f.payload_text ?? '',
      rating: (metadata.rating as string) || null,
      source_url: f.source_url ?? null,
      score: Number(f.score) || 0,
      metadata,
      classifications,
      created_at: f.created_at,
      occurred_at: f.occurred_at || f.created_at,
      content_date: f.occurred_at || f.created_at,
      excerpt: excerptsMap.get(f.id),
      similarity: toNumberOrUndefined(f.similarity),
      text_rank: toNumberOrUndefined(f.text_rank),
      combined_score: toNumberOrUndefined(f.combined_score),
      score_breakdown: f.score_breakdown as ContentItem['score_breakdown'],
      origin_parent_id: f.origin_parent_id || null,
      root_origin_id: f.root_origin_id || f.origin_id || String(f.id),
      depth: f.depth ?? 0,
      interaction_type: f.interaction_type ?? undefined,
      interaction_status: f.interaction_status ?? undefined,
      interaction_input_schema: f.interaction_input_schema
        ? parseJsonObject(f.interaction_input_schema)
        : undefined,
      interaction_input: f.interaction_input ? parseJsonObject(f.interaction_input) : undefined,
      interaction_output: f.interaction_output
        ? parseJsonObject(f.interaction_output)
        : undefined,
      interaction_error: f.interaction_error ?? undefined,
      supersedes_event_id: f.supersedes_event_id == null ? null : Number(f.supersedes_event_id),
      // `superseded_by` is the denormalized forward edge (the newer row that
      // replaced this one). Its presence is exactly what makes a row the
      // tombstone/stale side of a supersede chain, so `is_superseded` lets a
      // caller reading the full chain (content_ids resolution) tell the live
      // head from the superseded history without re-deriving it.
      superseded_by: f.superseded_by == null ? null : Number(f.superseded_by),
      is_superseded: f.superseded_by != null,
      run_id: f.run_id == null ? null : Number(f.run_id),
      parent_context:
        parentContextMap.get(f.origin_parent_id as string) ??
        (f.parent_context as ContentItem['parent_context']) ??
        null,
      root_context: f.root_context as ContentItem['root_context'],
      permalink: buildResourcePermalink(ownerSlug, { kind: 'event', eventId: f.id }, baseUrl) ?? null,
    };
  });

  // Event rendering resolution tail: a metadata-only event ('empty') with no
  // authored payload_template falls back to a default render synthesized from
  // its event kind — the kind's authored jsonTemplate, else a field card built
  // from the kind's metadataSchema (same generator as entity auto-default). An
  // event with real body content (text/markdown/media) or an explicit template
  // is left untouched. Resolution rides the cached event_kinds registry, so the
  // per-event lookups are cheap and bounded to the metadata-only minority.
  await Promise.all(
    contentItems.map(async (item) => {
      if (item.payload_template || item.payload_type !== 'empty') return;
      if (!item.metadata || Object.keys(item.metadata).length === 0) return;
      const kind = await resolveEventKindDefinition(
        item.semantic_type,
        organizationId,
        item.entity_ids
      );
      if (!kind) return;
      const root = resolveEntityRender(kind.jsonTemplate, kind.metadataSchema);
      if (!root) return;
      item.payload_template = { root };
      item.payload_type = 'json_template';
      item.payload_data = item.metadata;
    })
  );

  return contentItems;
}
/**
 * Tool: read_knowledge — SQL query building and the direct list branches
 * (content_ids lookup, include_superseded history listing, classification
 * stats aggregation).
 */

import { type DbClient, pgBigintArray, pgTextArray } from '../../db/client';
import {
  buildConnectionVisibilityClause,
  buildEntityLinkUnion,
  fetchEntityIdentityScopes,
} from '../../utils/content-search';
import logger from '../../utils/logger';
import { validateNumericId } from '../../utils/sql-validation';
import type { GetContentArgs } from './schema';
import type { ClassificationStatsRow, ContentRow, GetContentResult } from './types';

/** Connection-visibility scope derived from the tool context. */
interface VisibilityScope {
  organizationId: string;
  userId: string | null;
}

/** Shared shape returned by the direct list branches. */
interface ListPageResult {
  rawContent: ContentRow[];
  total: number;
  /**
   * Distinct-lineage count, set only by the content_ids branch where one id can
   * expand to a whole supersede chain. `total` counts returned rows; this counts
   * the atomic chains those rows collapse into.
   */
  chainTotal?: number;
  pageInfo: GetContentResult['page'];
}

/**
 * Build the common SELECT columns, JOINs, and classification subquery
 * used by both the content_ids and include_superseded query branches.
 */
function buildContentQuery(opts: {
  table: string;
  alias: string;
  /** Extra JOIN clause(s) spliced in before the fixed connection/oauth joins. */
  join?: string;
  where: string;
  orderBy: string;
  limit: number;
  offset: number;
}): string {
  const { table, alias: a, join = '', where, orderBy, limit, offset } = opts;
  return `
    SELECT
      ${a}.id,
      ${a}.entity_ids,
      ${a}.payload_text,
      ${a}.title,
      ${a}.author_name,
      ${a}.source_url,
      ${a}.occurred_at,
      ${a}.semantic_type,
      ${a}.origin_id,
      ${a}.origin_parent_id,
      COALESCE(${a}.origin_parent_id, ${a}.origin_id) as root_origin_id,
      CASE WHEN ${a}.origin_parent_id IS NULL THEN 0 ELSE 1 END as depth,
      ${a}.origin_type,
      ${a}.payload_type,
      ${a}.payload_data,
      ${a}.payload_template,
      ${a}.attachments,
      ${a}.score,
      ${a}.metadata,
      ${a}.created_at,
      COALESCE(${a}.connector_key, c.connector_key) as platform,
      ${a}.interaction_type,
      ${a}.interaction_status,
      ${a}.interaction_input_schema,
      ${a}.interaction_input,
      ${a}.interaction_output,
      ${a}.interaction_error,
      ${a}.supersedes_event_id,
      ${a}.superseded_by,
      ${a}.run_id,
      oc.client_name,
      -- Per-event classifications keyed by classifier attribute, matching the
      -- list/search path shape so exact reads (content_ids / include_superseded)
      -- surface a manual classifiers.classify immediately (#2050). One row per
      -- (event, classifier): source priority user then llm then embedding,
      -- newest first -- the same dedup rule as buildLatestClassificationsCteSql.
      COALESCE(
        (
          SELECT jsonb_object_agg(
            lc.attribute_key,
            jsonb_build_object(
              'values', lc.values,
              'confidences', lc.confidences,
              'source', lc.source,
              'is_manual', lc.is_manual
            )
          )
          FROM (
            SELECT
              fcl.attribute_key,
              cc."values" AS values,
              cc.confidences,
              cc.source,
              cc.is_manual,
              ROW_NUMBER() OVER (
                PARTITION BY cc.event_id, cc.classifier_id
                ORDER BY
                  CASE cc.source WHEN 'user' THEN 1 WHEN 'llm' THEN 2 ELSE 3 END,
                  cc.created_at DESC
              ) AS rn
            FROM event_classifications cc
            JOIN classify_facet fcl ON fcl.id = cc.classifier_id
            WHERE cc.event_id = ${a}.id AND cc.classifier_id IS NOT NULL
          ) lc
          WHERE lc.rn = 1
        ),
        '{}'::jsonb
      ) as classifications
    FROM ${table} ${a}
    ${join}
    LEFT JOIN connections c ON c.id = ${a}.connection_id
    LEFT JOIN oauth_clients oc ON oc.id = ${a}.client_id
    WHERE ${where}
    ORDER BY ${orderBy}
    LIMIT ${limit}
    OFFSET ${offset}
  `;
/**
 * Tool: read_knowledge — result/row type definitions and small parse helpers.
 */

import { type Static, Type } from '@sinclair/typebox';
import type { ContentItem } from '@lobu/connector-sdk';

// ============================================
// Type Definitions
// ============================================

export type { ContentItem };

/** Classifier configuration returned for watcher mode (for worker embedding generation) */
export interface ClassifierConfig {
  slug: string;
  extraction_config: Record<string, unknown> | null;
  attribute_values: Record<
    string,
    {
      description?: string;
      examples?: string[];
      embedding?: number[] | null;
    }
  >;
}

/**
 * Result of `read_knowledge`. TypeBox-first and the SINGLE source of truth:
 * `GetContentResult` is `Static<>`-derived from this schema, which is also the
 * tool's `outputSchema`. `ContentItem` (a 90-field type in
 * `@lobu/connector-sdk`, a published package) and the behavior-mode
 * `ClassifierConfig`/`UnprocessedRange` payloads are modeled as `unknown`
 * inline — they're opaque over the wire, and mirroring them here would be a
 * brittle second source that drifts from the SDK. The envelope (content list,
 * total, pagination, behavior-mode flags) is precise.
 */
export const GetContentResultSchema = Type.Object({
  content: Type.Array(Type.Unknown()),
  total: Type.Integer(),
  /**
   * content_ids reads only. `total` counts returned rows (a supersede chain
   * expands to all its rows); `chain_total` counts the distinct lineages those
   * rows collapse into — i.e. how many of the requested ids resolved to a thing.
   */
  chain_total: Type.Optional(Type.Integer()),
  page: Type.Object({
    limit: Type.Integer(),
    offset: Type.Integer(),
    has_more: Type.Boolean(),
    has_older: Type.Optional(Type.Boolean()),
    has_newer: Type.Optional(Type.Boolean()),
    next_cursor: Type.Optional(
      Type.Object({ occurred_at: Type.String(), id: Type.Integer() })
    ),
  }),
  classification_stats: Type.Optional(
    Type.Record(Type.String(), Type.Record(Type.String(), Type.Integer()))
  ),
  /**
   * Permalink for the entity-scoped events listing in the public web app.
   * LLM agents calling `read_knowledge` over MCP read this from the response
   * and format it into chat replies; there is no programmatic consumer in
   * this repo, but removing the field breaks that user-facing behavior.
   */
  view_url: Type.Optional(Type.String()),
  // Behavior-mode fields (only present when behavior_id is provided)
  window_token: Type.Optional(Type.String()),
  window_start: Type.Optional(Type.String()),
  window_end: Type.Optional(Type.String()),
  extraction_schema: Type.Optional(Type.Record(Type.String(), Type.Unknown())),
  sources: Type.Optional(Type.Record(Type.String(), Type.Array(Type.Unknown()))),
  /**
   * Behavior-bound entities as structured rows (id, name, type, metadata,
   * field_controls). field_controls marks human-owned field values the agent
   * must not overwrite without new evidence.
   */
  entities: Type.Optional(Type.Array(Type.Unknown())),
  classifiers: Type.Optional(Type.Array(Type.Unknown())),
  unprocessed_ranges: Type.Optional(Type.Array(Type.Unknown())),
  reactions_guidance: Type.Optional(Type.String()),
  /** Summary of this Behavior's recent reactions (self-learning context). */
  past_reactions: Type.Optional(Type.String()),
  /** Summary of recent human feedback on this Behavior's output. */
  past_feedback: Type.Optional(Type.String()),
  available_operations: Type.Optional(
    Type.Array(
      Type.Object({
        connection_id: Type.Integer(),
        operation_key: Type.String(),
        name: Type.String(),
        kind: Type.Union([Type.Literal('read'), Type.Literal('write')]),
        requires_approval: Type.Boolean(),
      })
    )
  ),
  total_count: Type.Optional(Type.Integer()),
  total_count_chars: Type.Optional(Type.Integer()),
  estimated_tokens: Type.Optional(Type.Integer()),
  token_warning: Type.Optional(Type.String()),
  entity_summary: Type.Optional(
    Type.Array(
      Type.Object({
        entity_id: Type.Integer(),
        name: Type.String(),
        entity_type: Type.String(),
        result_count: Type.Integer(),
      })
    )
  ),
  hints: Type.Optional(Type.Array(Type.String())),
});
export type GetContentResult = Static<typeof GetContentResultSchema>;

// ============================================
// Database Row Types (for query result typing)
// ============================================

/** Simple row with just an id field */
export interface IdRow {
  id: number;
}

/** Row type for classification stats aggregation */
export interface ClassificationStatsRow {
  classifier_slug: string;
  value: string;
  count: string | number;
}

/** Row type for raw content query results (union of all possible sources) */
export interface ContentRow {
  id: number;
  entity_ids: number[] | string; // string from some query sources
  platform: string;
  origin_id?: string | null;
  semantic_type: string;
  origin_type?: string | null;
  payload_type?: 'text' | 'markdown' | 'json_template' | 'media' | 'empty' | null;
  payload_text?: string | null;
  payload_data?: Record<string, unknown> | null;
  payload_template?: Record<string, unknown> | null;
  attachments?: unknown[] | null;
  author_name?: string | null;
  title: string | null;
  source_url?: string | null;
  score: number;
  metadata: Record<string, unknown> | null;
  classifications: Record<string, unknown> | null;
  created_at: string;
  occurred_at?: string | null;
  similarity?: number | null;
  text_rank?: number | null;
  combined_score?: number | null;
  score_breakdown?: Record<string, unknown> | null;
  origin_parent_id?: string | null;
  root_origin_id?: string;
  depth?: number;
  interaction_type?: 'none' | 'approval' | null;
  interaction_status?: 'pending' | 'approved' | 'rejected' | 'completed' | 'failed' | null;

		return [...seenKeys]
			.map((key) => {
				const definition = definitionsByKey.get(key);
				return {
					key,
					name: definition?.name || key,
					description: definition?.description,
					icon: definition?.icon,
					faviconDomain: extractOAuthDomain(definition?.auth_schema),
				};
			})
			.sort((left, right) => left.name.localeCompare(right.name));
	}, [effectiveConnectorDefinitions]);

	// Fetch events with infinite scroll — gate by auth state so private orgs
	// don't issue spurious 404s against /public/knowledge/search. Also gate on
	// `isReady` so the transient (isAuthenticated=false, isReady=false) bootstrap
	// window doesn't fire the public query for an authenticated user.
	const authInfiniteQuery = useInfiniteContentWithFilters(
		isReady && canManageWorkspace ? organizationId : null,
		effectiveEntityId,
		filters,
		ownerSlug,
	);
	const publicInfiniteQuery = usePublicInfiniteContentWithFilters(
		canReadPublicWorkspace ? ownerSlug : null,
		effectiveEntityId,
		filters,
	);
	// While auth/membership is bootstrapping, both queries are disabled so either
	// side is empty; default to the auth side so the rendered query shape is
	// consistent.
	const infiniteQuery = canReadPublicWorkspace
		? publicInfiniteQuery
		: authInfiniteQuery;
	const {
		data: infiniteData,
		isLoading,
		error,
		fetchNextPage,
		hasNextPage,
		isFetchingNextPage,
	} = infiniteQuery;

	const contents = useMemo(
		() => infiniteData?.pages.flatMap((p) => p.content) ?? [],
		[infiniteData],
	);
	const firstPage = infiniteData?.pages[0];
	const total = firstPage?.total ?? 0;
	const classificationStats = firstPage?.classification_stats;
	// Drill-down banner label for the URL ?entity_id=… scope (only on the org-wide
	// Memory page; the entity tab gets its scope from the prop, no banner). The
	// name is read off the results since there's no entity-by-id lookup hook.
	const entityFilterLabel =
		filters.entityId != null
			? `Showing memory for ${contents[0]?.entity_name ?? "this entity"}`
			: null;
	const hasCursorInUrl = !!(
		filters.beforeOccurredAt || filters.afterOccurredAt
	);
	const useDateFeed = isDateFeedMode(filters);

	// Update URL with scroll position when new pages are loaded (date feed mode)
	const lastPage = infiniteData?.pages[infiniteData.pages.length - 1];
	const lastLoadedItem = lastPage?.content[lastPage.content.length - 1];
	useEffect(() => {
		if (!useDateFeed || !lastLoadedItem || infiniteData?.pages.length === 1)
			return;
		updateUrlFilters({
			beforeOccurredAt: lastLoadedItem.occurred_at,
			beforeId: lastLoadedItem.id,
		});
	}, [
		lastLoadedItem?.id,
		useDateFeed,
		updateUrlFilters,
		infiniteData?.pages.length,
		lastLoadedItem,
	]);

	const goToLatest = useCallback(() => {
		updateFilters({
			beforeOccurredAt: undefined,
			beforeId: undefined,
			afterOccurredAt: undefined,
			afterId: undefined,
		});
		window.scrollTo({ top: 0, behavior: "smooth" });
	}, [updateFilters]);

	// Infinite scroll sentinel
	const sentinelRef = useScrollSentinel({
		onIntersect: () => fetchNextPage(),
		enabled: !!hasNextPage && !isFetchingNextPage,
	});

	const [expandedBehaviorGroups, setExpandedBehaviorGroups] = useState<Set<string>>(
		new Set(),
	);
	const toggleBehaviorGroup = (key: string) => {
		const newSet = new Set(expandedBehaviorGroups);
		if (newSet.has(key)) {
			newSet.delete(key);
		} else {
			newSet.add(key);
		}
		setExpandedBehaviorGroups(newSet);
	};

	// Timeline rows: first collapse supersede chains (pending→executing→completed
	// become one head + history), then thread-group each head's replies. A chain
	// member folded into a head's history no longer opens its own row, so a run's
	// lifecycle reads as a single, followable node instead of N near-duplicates.
	const timelineRows = useMemo(() => {
		const collapsed = collapseSupersedeChains(contents);
		const heads = collapsed.map((c) => c.head);
		const collapsedByHeadId = new Map(collapsed.map((c) => [c.head.id, c]));
		const threadGroups = groupContentByThread(heads);
		return Array.from(threadGroups.entries()).map(([rootId, group]) => {
			const mainContent = group.root || group.replies[0];
			const node = mainContent
				? collapsedByHeadId.get(mainContent.id)
				: undefined;
			return {
				rootId,
				group,
				history: node?.history ?? [],
				runId: node?.runId ?? null,
			};
		});
	}, [contents]);
	const [expandedThreads, setExpandedThreads] = useState<Set<string>>(
		new Set(),
	);
	const [expandedHistory, setExpandedHistory] = useState<Set<string>>(
		new Set(),
	);
	const [showDeepReplies, setShowDeepReplies] = useState<Set<string>>(
		new Set(),
	);

	const toggleThread = (rootId: string) => {
		const newSet = new Set(expandedThreads);
		if (newSet.has(rootId)) {
			newSet.delete(rootId);
		} else {
			newSet.add(rootId);
		}
		setExpandedThreads(newSet);
	};

	const toggleHistory = (rootId: string) => {
		const newSet = new Set(expandedHistory);
		if (newSet.has(rootId)) {
			newSet.delete(rootId);
		} else {
			newSet.add(rootId);
		}
		setExpandedHistory(newSet);
	};

	const toggleDeepReplies = (rootId: string) => {
		const newSet = new Set(showDeepReplies);
		if (newSet.has(rootId)) {
			newSet.delete(rootId);
		} else {
			newSet.add(rootId);
		}
		setShowDeepReplies(newSet);
	};

	// Keep relative timestamps stable while the user is on the page.
	const sampleEvents = useMemo(() => buildSampleEvents(), []);

	// Handle date selection from timeline
	const handleTimelineSelect = (start: Date, end: Date) => {
		updateFilters({ dateRange: [start, end] });
	};

	// Classification filter toggle
	const handleClassificationToggle = (slug: string, value: string) => {
		const current = filters.classificationFilters || {};
		const values = current[slug] || [];
		const updated = values.includes(value)
			? values.filter((v) => v !== value)
			: [...values, value];

		const newFilters: ClassificationFilters = { ...current };
		if (updated.length > 0) {
			newFilters[slug] = updated;
		} else {
			delete newFilters[slug];
			// Clear child classifier filters when parent is fully deselected
			for (const group of classifierGroups) {
				for (const c of group.classifiers) {
					if (c.parentSlug === slug) {
						delete newFilters[c.slug];
					}
				}
			}
		}
		updateFilters({ classificationFilters: newFilters });
	};

	if (error) return <TabErrorState label="knowledge" />;

	// Auth still resolving — both data queries are disabled, but the filter
	// bar + count placeholder still render so the user sees the page chrome
	// from the first frame. Treated like any other in-flight data state
	// below so the same list-skeleton renders.
	const isAuthLoading = !isReady || (isAuthenticated && isOrgLoading);
	const isListLoading = isAuthLoading || isLoading;

	const isInitialEmptyState = !isListLoading && total === 0 && !hasFilters;

	const emptyStateDescription = isAuthenticated
		? canManageWorkspace
			? "Activity is the workspace's live feed — every message, email, file, and record a connector pulls in lands here as an event. Connect your data to start collecting."
			: "Activity is the workspace's live feed of connector events. Join this workspace to add connectors and collect knowledge here."
		: "No public knowledge items are available yet";
	const showEmptyStateAction = Boolean(canManageWorkspace && ownerSlug);

	return (
		<TooltipProvider>
			<div className="space-y-4">
				{/* Memory: filters stick to the top of the pane. `top-12` used to
				    clear the Events/Entities tab strip, which the sidebar replaced —
				    leaving a gap that started this page's content lower than every
				    sibling. Elsewhere: normal flow filter row. */}
				<div
					className={
						hideSourceFilter
							? "sticky top-0 z-10 -mx-4 space-y-3 bg-background px-4 pb-3 lg:-mx-6 lg:px-6"
							: undefined
					}
				>
					<EventsFilterBar
