} from "@/components/connectors/connector-page-shell";
import {
	DETAIL_CRUMB_LINK_CLASS,
	DetailBreadcrumb,
	DetailHeader,
} from "@/components/connectors/detail-header";
import { PageSection } from "@/components/connectors/page-section";
import { useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";
import { useConnectedClients, useRevokeMcpClient } from "@/lib/api/clients";
import { groupClients, relativeTime } from "@/lib/connectors/client-rows";

/**
 * A connected MCP client, rendered through the connectors detail route as
 * `client:{id}`.
 *
 * This page carries Revoke, which is the reason the standalone
 * `/connectors/apps` page could be deleted in the same change rather than
 * waiting on Recent: revoking a grant had exactly one home in the SPA, and it
 * moved here.
 *
 * Identity deliberately shows BOTH names. `client_name` is what the app
 * registered as and is the row's identity; `clientInfo.name` names the process
 * driving the connection. Before they were separated, Owletto for Mac and
 * Claude both rendered as "claude-code" — two rows, same title, and no way to
 * tell which grant Revoke would kill.
 */
export function ClientDetail({
	ownerSlug,
	clientId,
}: {
	ownerSlug: string;
	clientId: string;
}) {
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const { data: clients = [], isLoading } = useConnectedClients(null);
	const revoke = useRevokeMcpClient();
	const [confirming, setConfirming] = useState(false);

	const group = useMemo(
		() => groupClients(clients).find((g) => g.clientId === clientId),
		[clients, clientId],
	);
	// The raw registrations behind the group — each is a separate OAuth grant.
	const registrations = useMemo(
		() => clients.filter((c) => group?.clientIds.includes(c.id)),
		[clients, group],
	);

	if (isLoading) {
		return (
			<ConnectorPageColumn className="space-y-4">
				<div className="flex items-center gap-2">
					<Skeleton className="h-6 w-6 rounded" />
					<Skeleton className="h-5 w-40" />
				</div>
				<Skeleton className="h-24 w-full rounded-lg" />
			</ConnectorPageColumn>
		);
	}

	if (!group) {
		return (
			<ConnectorPageColumn className="space-y-3">
				<p className="text-sm text-muted-foreground">
					This app isn't connected to this workspace, so its details aren't
					available.
				</p>
				<Link
					to="/$owner/connectors"
					params={{ owner: ownerSlug }}
					search={{}}
					className="text-sm text-primary hover:underline"
				>
					Back to connectors
				</Link>
			</ConnectorPageColumn>
		);
	}

	const primary = registrations[0];
	const redirectUris = (primary?.details?.redirectUris ?? []) as string[];
	const rows: Array<{ label: string; value: string }> = [
		{ label: "Registered", value: group.title },
		...(group.drivenBy && group.drivenBy !== group.title
			? [{ label: "Driven by", value: group.drivenBy }]
			: []),
		...(primary?.platform ? [{ label: "Software", value: primary.platform }] : []),
		...(redirectUris.length > 0
			? [{ label: "Redirects", value: redirectUris.join(", ") }]
			: []),
		{ label: "Granted by", value: group.linkedUser ?? "—" },
		{
			label: "Last active",
			value: group.connected ? relativeTime(group.lastSeenAt) : "disconnected",
		},
		{
			label: "Registrations",
			value: String(group.clientIds.length),
		},
	];

	return (
		<div className="flex flex-1 flex-col">
			<ConnectorPageShell
				header={
					<DetailHeader
						breadcrumb={
							<DetailBreadcrumb
								crumbs={[
									<Link
										key="connectors"
										to="/$owner/connectors"
										params={{ owner: ownerSlug }}
										search={{}}
										className={DETAIL_CRUMB_LINK_CLASS}
									>
										Connectors
									</Link>,
								]}
							/>
						}
						icon={
							<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border">
								<AppWindow className="h-4 w-4 text-muted-foreground" />
							</span>
						}
						title={group.title}
						badge={
							<Badge
								variant={group.connected ? "secondary" : "outline"}
								className="text-[10px]"
							>
								{group.connected ? "Connected" : "Disconnected"}
							</Badge>
						}
						caption={`Connects into this workspace over MCP as ${
							group.linkedUser ?? "a member"
						}, with that person's access.`}
					/>
				}
			>
				<PageSection title="Registration">
					<div className="overflow-hidden rounded-lg border text-xs">
						<dl className="divide-y">
							{rows.map((row) => (
								<div key={row.label} className="flex gap-3 px-3 py-2">
									<dt className="w-28 shrink-0 text-muted-foreground">
										{row.label}
									</dt>
									<dd className="min-w-0 flex-1 break-words">{row.value}</dd>
								</div>
							))}
						</dl>
					</div>
				</PageSection>

				{isAdmin && group.connected ? (
					<PageSection title="Access">
						<div className="space-y-2 rounded-lg border p-3">
							<p className="text-xs text-muted-foreground">
								Revoking disconnects every registration this app holds
								{group.clientIds.length > 1
									? ` (${group.clientIds.length} of them)`
									: ""}{" "}
								and kills its live sessions. It can reconnect by authorizing
								again.
							</p>
							{confirming ? (
								<div className="flex items-center gap-2">
									<Button
										variant="destructive"
										size="sm"
										className="h-7 px-2 text-xs"
										disabled={revoke.isPending}
										onClick={() =>
											revoke.mutate(
												{ clientId: group.clientIds[0], scope: "all" },
												{ onSettled: () => setConfirming(false) },
											)
										}
									>
										{revoke.isPending ? "Revoking…" : "Confirm revoke"}
									</Button>
									<Button
										variant="ghost"
										size="sm"
										className="h-7 px-2 text-xs"
										disabled={revoke.isPending}
										onClick={() => setConfirming(false)}
									>
										Cancel
									</Button>
								</div>
							) : (
								<Button
									variant="outline"
									size="sm"
									className="h-7 px-2 text-xs text-destructive hover:text-destructive"
									onClick={() => setConfirming(true)}
								>
									Revoke
								</Button>
							)}
						</div>
					</PageSection>
				) : null}
			</ConnectorPageShell>
		</div>
	);
}
									<div className="min-w-0 flex-1">
										<div className="flex flex-wrap items-center gap-2">
											<span className="truncate text-sm font-medium">
												{display.name}
											</span>
											<FacetChips facets={facets} />
										</div>
										<p className="truncate text-xs text-muted-foreground">
											{meta}
										</p>
									</div>
									{needsSetup ? (
										<Badge variant="secondary" className="shrink-0 text-[10px]">
											Needs setup
										</Badge>
									) : null}
								</>
							);

							return device ? (
								<Link
									key={connector.key}
									to="/$owner/connectors/device/$deviceId"
									params={{ owner: ownerSlug, deviceId: device.id }}
									className={rowClassName}
								>
									{rowBody}
								</Link>
							) : (
								<Link
									key={connector.key}
									to="/$owner/connectors/$connectorKey"
									params={{ owner: ownerSlug, connectorKey: connector.key }}
									className={rowClassName}
								>
									{rowBody}
								</Link>
							);
						},
					)}

					{/* Connected apps sit in the same list, not a section of their own.
					    They are the one INBOUND thing here — ChatGPT calling in with a
					    person's access rather than something an agent reaches out to —
					    and their meta line says so. That distinction did not earn a
					    second bordered box with its own heading and paragraph: it made
					    the page read as two inventories when it is one. */}
					{clientRowsShown.map((group, idx) => (
						<Link
							key={group.key}
							to="/$owner/connectors/client/$clientId"
							params={{ owner: ownerSlug, clientId: group.clientId }}
							className={listRowClass(items.length + idx, rowCount)}
						>
							<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border">
								<AppWindow className="h-4 w-4 text-muted-foreground" />
							</span>
							<div className="min-w-0 flex-1">
								<div className="flex flex-wrap items-center gap-2">
									<span className="truncate text-sm font-medium">
										{group.title}
									</span>
									{group.clientIds.length > 1 ? (
										<span className="shrink-0 rounded-md bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
											{group.clientIds.length} registrations
										</span>
									) : null}
								</div>
								<p className="truncate text-xs text-muted-foreground">
									Connected app · {clientRowMeta(group)}
								</p>
							</div>
							<span
								role="img"
								aria-label={group.connected ? "Connected" : "Disconnected"}
								className={`h-2 w-2 shrink-0 rounded-full ${
									group.connected ? "bg-emerald-500" : "bg-muted-foreground/40"
								}`}
							/>
						</Link>
					))}
				</div>
			)}

			{/* What you could still connect: the Mac app, the extension, the CLI, an
			    MCP client. Dashed rather than headed — these are not things this
			    workspace has, and a heading over four permanent rows turns setup
			    instructions into a fixture of the page. Each one drops off the list
			    as soon as it has paired something. */}
			{appEntries.length > 0 ? (
				<div className="overflow-hidden rounded-lg border border-dashed">
					{appEntries.map((app, idx) => (
						<Link
							key={app.id}
							to="/$owner/connectors/app/$appId"
							params={{ owner: ownerSlug, appId: app.id }}
							className={listRowClass(idx, appEntries.length)}
						>
							<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border border-dashed">
								{app.icon}
							</span>
							<div className="min-w-0 flex-1">
								<p className="truncate text-sm font-medium">{app.name}</p>
								<p className="truncate text-xs text-muted-foreground">
									{app.tagline}
								</p>
							</div>
							<span className="shrink-0 text-xs">Set up</span>
						</Link>
					))}
				</div>
			) : null}
		</div>
