const SCRIPT_FIELDS = {
  script: Type.String({
    description:
      "TypeScript source. Must `export default async (ctx, client) => { ... }` — `ctx` is `{ organization_id, user_id, mode, sleep(ms) }`, where `await ctx.sleep(ms)` provides a bounded, abort-aware 0–30000ms polling delay; unrestricted timer globals are unavailable. `client` is the ClientSDK. The script's return value comes back as `return_value` in the result. Use `search_sdk` to discover SDK methods and `ctx.sleep`.",
    minLength: 1,
    maxLength: 100_000,
  }),
  timeout_ms: Type.Optional(
    Type.Number({
      description:
        "Wall-clock budget. Default 60000 (max 180000 — device-bound operations may wait ~155s).",
      minimum: 100,
      maximum: MAX_SCRIPT_TIMEOUT_MS,
    }),
  ),
};

export const RunSchema = Type.Object({
  ...SCRIPT_FIELDS,
  dry_run: Type.Optional(
    Type.Boolean({
      description:
        "Preview mode. Read SDK calls still execute, but write/admin/external SDK calls are skipped and returned in side_effect_preview. Dry-run validates the SDK method path and access tier, but it does not execute the skipped handler or fully validate that handler's payload shape.",
    }),
  ),
});
export const QuerySchema = Type.Object(SCRIPT_FIELDS);
type RunArgs = Static<typeof RunSchema>;
type QueryArgs = Static<typeof QuerySchema>;

const SdkCallTraceEntrySchema = Type.Object({
  path: Type.String({ description: "Dotted SDK method path (e.g. entities.list)." }),
  orgPath: Type.Array(Type.String(), {
    description: "Org slugs traversed via client.org(...) before the call, if any.",
  }),
  access: Type.Union(
    [
      Type.Literal("read"),
      Type.Literal("write"),
      Type.Literal("external"),
      Type.Literal("admin"),
      Type.Literal("unknown"),
    ],
    { description: "Access class of the method." },
  ),
  args: Type.Array(Type.Unknown(), { description: "Call arguments (redacted + truncated)." }),
  skipped: Type.Boolean({
    description: "true when dry_run skipped this write/external call.",
  }),
});

