    const valid = advertisedArgNames(schema);
    errs.push(
      `unknown argument(s): ${unknown.join(', ')} — valid arguments${scope} are: ${valid.join(', ')}`
    );
  }
  throw new ToolUserError(`Invalid arguments for ${toolName}: ${errs.join('; ')}`);
}

