    await expect(
      executeTool('search_sdk', argsWithSecretA, {} as Env, authCtxFor('pat'))
    ).rejects.toThrow();
    await expect(
      executeTool('sear…583 tokens truncated…  const toolName = `probe_status_${status}`;
      await recordToolInvocationAudit({
