/**
 * A clicked activity/notification item that should open in the right-side peek
 * pane (instead of navigating to its dedicated page). The pane reuses the SAME
 * content component the dedicated page renders — never a duplicate.
 *
 * Peek target is sticky in the URL (`?peek=1&peek_run_id=…` etc.) so reloads,
 * sidepanel deep-links, and "click → query param" all share one path.
 */
export interface PeekItem {
	/** App-relative href of the destination (same string a plain click navigates to). */
	href: string;
	/** Title for the pane header. */
	title: string;
	/** The specific run this item represents (shows just that run, not the whole watcher). */
	runId?: number;
}

interface NotificationPeekValue {
	item: PeekItem | null;
	open: (item: PeekItem) => void;
	close: () => void;
}

const NotificationPeekContext = createContext<NotificationPeekValue | null>(
	null,
);

function titleForPeekHref(href: string, fallback?: string): string {
	if (fallback?.trim()) return fallback.trim();
	const dest = parsePeekHref(href);
	if (!dest) return "Details";
	if (dest.kind === "memory" && dest.runId != null) {
		return `Run #${dest.runId}`;
	}
	if (dest.kind === "behavior") {
		return dest.runId != null ? `Behavior run #${dest.runId}` : "Behavior";
	}
	return "Details";
}

/**
 * Provides peek state for everything inside the owner (workspace) layout — i.e.
 * the surfaces that render the activity timeline (agent chat empty-state, Home).
 * When no provider is present (e.g. outside workspace routes), `useNotificationPeek`
 * returns null so callers fall back to a normal navigate().
 *
 * URL contract: see `lib/peek-search.ts`. Opening the pane writes peek keys
 * onto the current route's search; closing omits them. Incoming search (deep
 * link / click) hydrates the pane.
 */
export function NotificationPeekProvider({
	children,
}: {
	children: ReactNode;
}) {
	const navigate = useNavigate();
	const location = useLocation();
	const params = useParams({ strict: false }) as { owner?: string };
	const owner = params.owner ?? "";

	const [item, setItem] = useState<PeekItem | null>(null);
	// URL → pane
	useEffect(() => {
		if (!owner) {
			setItem(null);
			return;
		}
		const search = location.search as Record<string, unknown>;
		if (!hasPeekFlag(search)) {
			setItem(null);
			return;
		}
		const peekSearch = pickPeekSearch(search);
		const href = destinationHrefFromPeekSearch(owner, peekSearch);
		const dest = href ? parsePeekHref(href) : null;
		if (!href || !dest) {
			setItem(null);
			return;
		}
		const runId =
			dest.kind === "memory"
				? dest.runId
				: dest.kind === "behavior"
					? dest.runId
					: undefined;
		setItem((prev) => {
			if (prev?.href === href && prev.runId === runId) return prev;
			return {
				href,
				title: titleForPeekHref(
					href,
					prev?.href === href ? prev.title : undefined,
				),
				runId,
			};
		});
	}, [location.search, owner]);

	const open = useCallback(
		(next: PeekItem) => {
			const peekSearch = peekSearchFromDestinationHref(next.href);
			if (!peekSearch) {
				// Non-peekable: still set local state so callers that already
				// gated on parsePeekHref keep working.
				setItem(next);
				return;
			}
			if (
				next.runId != null &&
				peekSearch.peek_behavior &&
				!peekSearch.peek_behavior_run_id
			) {
				peekSearch.peek_behavior_run_id = String(next.runId);
			}
			setItem(next);
			void navigate({
				// Stay on the current path; only stick peek keys into search.
				search: ((prev: Record<string, unknown>) =>
					mergePeekSearch(prev, peekSearch)) as never,
				replace: true,
			});
		},
		[navigate],
	);

	const close = useCallback(() => {
		setItem(null);
		void navigate({
			search: ((prev: Record<string, unknown>) =>
				omitPeekSearch(prev)) as never,
			replace: true,
		});
	}, [navigate]);

	const value = useMemo(() => ({ item, open, close }), [item, open, close]);
	return (
		<NotificationPeekContext.Provider value={value}>
			{children}
		</NotificationPeekContext.Provider>
	);
}

