import { useQuery } from "@tanstack/react-query";
import { apiCall } from "./core";

export type ActivityCard = {
	id: string;
	kind: string;
	title: string;
	body: string | null;
	at: string;
	status: string | null;
	count: number;
	href: string | null;
	unread?: boolean;
	notification_id?: number;
	run_id?: number;
	/**
	 * Kind of pending interaction behind this notification (events
	 * `interaction_type` vocabulary — 'approval' today). Clients pick the UI
	 * for the type; new interaction kinds extend the value, not the card shape.
	 */
	interaction_type?: string;
	/**
	 * Live interaction state from its authoritative per-type source. For
	 * 'approval': 'pending' | 'approved' | 'rejected' (the run's state machine).
	 */
	interaction_status?: string;
	/** Server policy: this interaction can be completed inline from the feed. */
	interaction_inline?: boolean;
	member_run_ids?: number[];
	connection_id?: number;
	behavior_id?: number;
};

type ListActivityResult = {
	action: "list_activity";
	items: ActivityCard[];
	total: number;
	limit: number;
};

export type ActivityFeedOpts = {
	limit?: number;
	includeNotifications?: boolean;
	includeRuns?: boolean;
	aggregate?: boolean;
	kinds?: string[];
	/** Scope the feed to a single agent's runs (drops notifications server-side). */
	agentId?: string;
};

/**
 * Workspace attention feed (manage_operations.list_activity) — aggregated
 * notifications + user-facing runs with deep-links.
 */
export function useActivityFeed(
	ownerSlug: string | null,
	opts?: ActivityFeedOpts,
) {
	const limit = opts?.limit ?? 24;
	const aggregate = opts?.aggregate !== false;
	const includeNotifications = opts?.includeNotifications !== false;
	const includeRuns = opts?.includeRuns !== false;
	const kinds = opts?.kinds;
	const agentId = opts?.agentId;

	return useQuery({
		queryKey: [
			"activity-feed",
			ownerSlug ?? null,
			limit,
			aggregate,
			includeNotifications,
			includeRuns,
			kinds?.join(",") ?? null,
			agentId ?? null,
		],
		queryFn: async () => {
			const res = await apiCall<ListActivityResult>(
				"manage_operations",
				{
					action: "list_activity",
					limit,
					aggregate,
					include_notifications: includeNotifications,
					include_runs: includeRuns,
					...(kinds?.length ? { kinds } : {}),
					...(agentId ? { agent_id: agentId } : {}),
				},
				ownerSlug ? { slug: ownerSlug } : undefined,
			);
			return res.items ?? [];
		},
		enabled: !!ownerSlug,
		staleTime: 15_000,
		refetchInterval: 30_000,
	});
}
// Runs list — infinite query over `manage_operations` `list_runs`, scoped to a
// connection, connector, device (every connection pinned to it), or single feed.
import { useInfiniteQuery, useQuery } from '@tanstack/react-query';
import { agentsUrl } from './agents';
import { apiCall, fetchWithTimeout, getPathScope } from './core';

export interface RunListItem {
  id: number;
  run_type: string;
  behavior_id: number | null;
  status: string;
  connection_id: number | null;
  feed_id: number | null;
  connector_key: string | null;
  connector_version: string | null;
  operation_key: string | null;
  approval_status: string | null;
  items_collected: number | null;
  error_message: string | null;
  checkpoint: Record<string, unknown> | null;
  created_at: string;
  completed_at: string | null;
  feed_key: string | null;
  feed_display_name: string | null;
  connection_display_name: string | null;
  device_worker_id: string | null;
}

interface ListRunsResult {
  action: 'list_runs';
  runs: RunListItem[];
  total: number;
  limit: number;
  offset: number;
  has_more: boolean;
}

export type RunScope =
  | { connectionId: number }
  | { deviceId: string }
  | { feedId: number }
  /** Every run attributed to this connector (connector Overview). */
  | { connectorKey: string };

export interface RunQueryFilters {
  /** Omit / empty → every run type. */
  runTypes?: string[];
  status?: string;
}

const PAGE_SIZE = 30;
const ACTIVE_STATUSES = new Set(['running', 'pending', 'claimed']);

type RunCursor = { before_id: number; before_created_at: string } | null;

function scopeKey(scope: RunScope): (string | number)[] {
  if ('connectionId' in scope) return ['connection', scope.connectionId];
  if ('deviceId' in scope) return ['device', scope.deviceId];
  if ('connectorKey' in scope) return ['connector', scope.connectorKey];
  return ['feed', scope.feedId];
}

function scopeParams(scope: RunScope): Record<string, unknown> {
  if ('connectionId' in scope) return { connection_ids: [scope.connectionId] };
  if ('deviceId' in scope) return { device_worker_id: scope.deviceId };
  if ('connectorKey' in scope) return { connector_key: scope.connectorKey };
  return { feed_ids: [scope.feedId] };
}

export function useInfiniteRuns(
  scope: RunScope | null,
  filters: RunQueryFilters,
  ownerSlug?: string,
) {
  return useInfiniteQuery({
    queryKey: [
      'runs-infinite',
      ownerSlug ?? null,
      scope ? scopeKey(scope) : null,
      filters.runTypes ?? null,
      filters.status ?? null,
    ],
    queryFn: async ({ pageParam }) => {
      const cursor = pageParam as RunCursor;
      return apiCall<ListRunsResult>(
        'manage_operations',
        {
          action: 'list_runs',
          ...scopeParams(scope as RunScope),
          ...(filters.runTypes && filters.runTypes.length > 0
            ? { run_types: filters.runTypes }
            : {}),
          ...(filters.status ? { status: filters.status } : {}),
          ...(cursor
            ? {
                before_id: cursor.before_id,
                before_created_at: cursor.before_created_at,
              }
            : {}),
          limit: PAGE_SIZE,
        },
        ownerSlug ? { slug: ownerSlug } : undefined,
      );
    },
    initialPageParam: null as RunCursor,
    getNextPageParam: (lastPage): RunCursor | undefined => {
      if (!lastPage.has_more) return undefined;
      const last = lastPage.runs[lastPage.runs.length - 1];
      if (!last) return undefined;
      return { before_id: last.id, before_created_at: last.created_at };
    },
    // Poll while any loaded run is still in flight; idle otherwise.
    refetchInterval: (query) => {
      const pages = query.state.data?.pages ?? [];
      const hasActive = pages.some((p) => p.runs.some((r) => ACTIVE_STATUSES.has(r.status)));
      return hasActive ? 5000 : false;
    },
    enabled: !!scope,
    staleTime: 15000,
  });
}

// Config-approval prefill — read a held builder proposal.
//
// When an admin drives the per-org builder agent to change ANOTHER agent's
// config, the write is server-gated into a pending `runs` row (see the builder
// gate in `agents.ts`). A Slack deep link routes the human to
// `/{owner}/agents/{agentId}/settings?run_id=42`; opening it reads the held
// proposal here so the real form can be prefilled for review. Served by the
// org-scoped agent router at `/api/:orgSlug/agents/:agentId/config/pending/:runId`
// — the SAME base `useAgentConfig` hits (`agentsUrl`), so no URL special-casing.

export interface PendingProposal {
  runId: number;
  resourceKind: 'agent' | 'behavior' | null;
import { getEmbeddedSessionToken } from '../embedded-auth';
import { captureApiError, captureApiException } from '../sentry';
import { getSubdomainOwner } from '../subdomain';
import { parseEntityPath } from '../url';

const DEFAULT_API_URL =
  typeof window !== 'undefined' ? window.location.origin : 'http://localhost:8787';
export const API_URL = import.meta.env.VITE_API_URL || DEFAULT_API_URL;

// In the extension's embedded iframe the session cookie isn't delivered, so
// authenticate same-origin API calls with the Bearer session token instead.
// Gated to the API origin so the token never leaks to a third-party URL; a no-op
// for normal web sessions (no token → cookie auth, unchanged).
function isApiOrigin(input: RequestInfo | URL): boolean {
  try {
    const href =
      typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
    const base = typeof window !== 'undefined' ? window.location.href : API_URL;
    return new URL(href, base).origin === new URL(API_URL).origin;
  } catch {
    return false;
  }
}

function withEmbeddedAuth(input: RequestInfo | URL, init?: RequestInit): RequestInit | undefined {
  const token = getEmbeddedSessionToken();
  if (!token || !isApiOrigin(input)) return init;
  const headers = new Headers(init?.headers);
  if (!headers.has('Authorization')) headers.set('Authorization', `Bearer ${token}`);
  return { ...init, headers };
}

/**
 * An API failure that retains the originating HTTP status.
 *
 * Callers used to get a bare `Error`, so every failure looked alike: TanStack
 * set `isError` for a 404 and a 500 identically, and a page keying its empty
 * state on that flag told people their organization did not exist whenever the
 * server was merely down.
 */
export class ApiError extends Error {
  readonly status: number;

  constructor(message: string, status: number) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
  }
}

/**
 * True when a request failed because the thing is not there (404). Narrow on
 * purpose: 403 is "exists, not yours", which warrants a different message.
 */
export function isNotFoundError(error: unknown): boolean {
  return error instanceof ApiError && error.status === 404;
}

/**
 * True when the SERVER failed, rather than the request being answered with a
 * refusal. Only 5xx and transport-level failures qualify.
 *
 * The distinction matters for empty states: a 401/403 means "log in" or "ask
 * for access" and has its own path through the UI, so lumping every non-404
 * into "something went wrong on our end" strands people on an error page
 * instead of sending them to sign in.
 */
export function isServerError(error: unknown): boolean {
  if (error instanceof ApiError) return error.status >= 500;
  if (!(error instanceof Error)) return false;
  // Not an `ApiError`, so the status did not survive. Recover it from the
  // `API error: <status>` message the older raw throws produced rather than
  // assuming a transport failure: reading a 401 as an outage is exactly the
  // bug this function exists to prevent, and it would come back silently the
  // next time a call site throws a plain `Error`.
  const status = /^API error: (\d{3})$/.exec(error.message)?.[1];
  if (status) return Number(status) >= 500;
  // No status anywhere: a genuine transport failure (offline, DNS, timeout)
  // never reached a server, which is an outage from the user's point of view.
  return true;
}

export async function apiErrorFor(
  response: Response,
  fallbackMessage?: string
): Promise<ApiError> {
  const fallback = fallbackMessage
    ? `${fallbackMessage}: ${response.status}`
    : `API error: ${response.status}`;
  return new ApiError(await getApiErrorMessage(response, fallback), response.status);
}

export async function getApiErrorMessage(
  response: Response,
  fallback = `API error: ${response.status}`
): Promise<string> {
  const raw = await response.text();
  if (!raw) return fallback;

  try {
    const parsed = JSON.parse(raw) as {
      error?: unknown;
      error_description?: unknown;
      message?: unknown;
    };
    if (typeof parsed.message === 'string' && parsed.message.length > 0) return parsed.message;
    if (
      typeof parsed.error_description === 'string' &&
      parsed.error_description.length > 0
    ) {
				<div className="mt-3 text-xs text-muted-foreground">
					All proposals reviewed.
				</div>
			)}
		</div>
	);
}

export function EventCard({
	content,
	isReply,
	showParentContext,
}: EventCardProps) {
	const [showFullText, setShowFullText] = useState(false);
	const peek = useNotificationPeek();
	// `currentOwner` is the slug the app puts in URLs (@user or org-slug).
	const { currentOwner } = useOrgContext();

	/**
	 * Open the event in the right-hand peek instead of navigating away.
	 *
	 * `peek.open()` writes `?peek=1&peek_run_id=…` into the URL, so a reload or a
	 * shared link reopens the same pane — the deep link comes for free, which is
	 * why the copy-permalink icon this replaced is gone.
	 *
	 * Only events that came from a run are peekable: `content.permalink` is the
	 * item's link on its ORIGIN (Slack, GitHub, …), not an app route, so it
	 * cannot drive this. `run_id` is the app-side identity, and
	 * `/{owner}/activity?run_ids=N` is the shape `parsePeekHref` accepts — the
	 * param is PLURAL and comma-separated, and only a single id is peekable.
	 * An event with no run has nothing to preview, so its card stays inert rather
	 * than becoming a button that does nothing.
	 */
	const peekHref =
		currentOwner && content.run_id != null
			? `/${currentOwner}/activity?run_ids=${content.run_id}`
			: null;
	const canPeek = Boolean(peek && peekHref && parsePeekHref(peekHref));
	const openPeek = () => {
		if (!peek || !peekHref) return;
		peek.open({
			href: peekHref,
			title: content.title ?? `Run #${content.run_id}`,
			runId: content.run_id ?? undefined,
		});
	};
	/**
	 * The card wraps its own controls — the score popover, "View original", "Show
	 * more", approval buttons. A bare onClick on the container fires for those
	 * too, so clicking any of them would ALSO open the peek. Ignore anything that
	 * originated inside an interactive descendant; only clicks on the card's own
	 * inert area count.
	 */
	const fromNestedControl = (event: React.SyntheticEvent) => {
		const target = event.target;
		if (!(target instanceof Element)) return false;
		const hit = target.closest(
			'a,button,input,select,textarea,[role="button"],[role="radio"]',
		);
		// The card itself carries role="button", so it matches its own selector —
		// compare against currentTarget or every click would be swallowed.
		return hit !== null && hit !== event.currentTarget;
	};
	const handleCardClick = (event: React.MouseEvent) => {
		if (fromNestedControl(event)) return;
		openPeek();
	};
	const handleCardKeyDown = (event: React.KeyboardEvent) => {
		if (event.key !== "Enter" && event.key !== " ") return;
		if (fromNestedControl(event)) return;
		event.preventDefault();
		openPeek();
	};
	const metadata = (content.metadata || {}) as Record<string, unknown>;

	// A watcher run's first-class change-set (what it created/updated inline). Its
	// own card — the diff is a property of the run, not the approval flow.
	if (content.semantic_type === "change_set") {
		return <RunChangeSetCard content={content} />;
	}

	const isOperationEvent =
		content.interaction_type === "approval" ||
		content.semantic_type === "operation" ||
		metadata.status != null ||
		metadata.action_key != null;

	// Action events get a dedicated approval UI
	if (isOperationEvent) {
		return <ActionApprovalCard content={content} />;
	}

	const roundedScore = Number.isFinite(content.score)
		? Math.round(content.score)
		: "-";

	const payloadType = content.payload_type || "text";
	const textContent = content.text_content || "";
	const shouldTruncate =
		(payloadType === "text" || payloadType === "markdown") &&
		textContent.length > 500;
	const displayText =
		shouldTruncate && !showFullText
			? `${textContent.slice(0, 500)}...`
			: textContent;

	// Well-known metadata fields (declared via eventKinds.metadataSchema)
	const thumbnail =
		(metadata.thumbnail_url as string | undefined) ||
		(metadata.thumbnail as string | undefined);
	const mediaUrl = metadata.media_url as string | undefined;
	const metadataEntries = getVisibleMetadataEntries(metadata);

	// Parse classifications
	const classifications = Object.entries(content.classifications || {}).flatMap(
		([slug, data]) => {
			const parsed = normalizeClassificationValues(data);
			return parsed.values.map((value) => ({
				slug,
				value,
				isManual: parsed.isManual,
			}));
		},
	);

	return (
		<div
			className={cn(
				isReply ? "border-l-2 border-l-muted pl-4" : "",
				canPeek &&
					"-mx-2 cursor-pointer rounded-lg px-2 py-1 transition-colors hover:bg-accent/40",
			)}
			{...(canPeek
				? {
						role: "button",
						tabIndex: 0,
						onClick: handleCardClick,
						onKeyDown: handleCardKeyDown,
					}
				: {})}
		>
			{/* Parent context for orphaned replies */}
			{showParentContext && content.parent_context && (
				<div className="mb-3 p-2 bg-muted/50 rounded-md text-sm">
					<div className="text-xs text-muted-foreground mb-1">Replying to:</div>
					<div className="font-medium">
						{content.parent_context.author_name}
					</div>
					<div className="text-muted-foreground line-clamp-2">
						{content.parent_context.text_content}
					</div>
				</div>
			)}

			{/* Header */}
			<div className="flex items-start justify-between gap-4 mb-2">
				<div className="flex-1 min-w-0">
					{content.title && (
						<h4 className="font-medium line-clamp-2 mb-1">{content.title}</h4>
					)}
					<div className="flex items-center gap-2 text-sm text-muted-foreground">
						{(() => {
							const source = deriveSourceLabel(content);
							// The badge duplicates the label when the label *is* the
							// connector (an event with no human author). Show the badge
							// only when it adds info beyond the label.
							const showBadge =
								!!content.platform && source !== sentenceCase(content.platform);
							return (
								<>
									{source && <span className="font-medium">{source}</span>}
									{showBadge && (
										<>
											{source && <span>·</span>}
											<Badge variant="outline" className="text-xs">
												{content.platform}
											</Badge>
										</>
									)}
								</>
							);
						})()}
					</div>
				</div>

				{/* Score */}
				<div className="flex items-center gap-2">
					{content.score_breakdown ? (
						<Popover>
							<PopoverTrigger asChild>
								<Button variant="ghost" size="sm" className="h-7 px-2">
									<span className="font-medium">{roundedScore}</span>
								</Button>
							</PopoverTrigger>
							<PopoverContent className="w-64" align="end">
								<div className="space-y-2">
									<h4 className="font-medium">Score Breakdown</h4>
									<ScoreBreakdown breakdown={content.score_breakdown} />
								</div>
							</PopoverContent>
						</Popover>
					) : (
						<Button variant="ghost" size="sm" className="h-7 px-2" disabled>
							<span className="font-medium">{roundedScore}</span>
						</Button>
					)}

					{content.source_url && (
						<Tooltip>
							<TooltipTrigger asChild>
								<Button variant="ghost" size="icon" className="h-7 w-7" asChild>
									<a
										href={content.source_url}
										target="_blank"
										rel="noopener noreferrer"
									>
										<ExternalLink className="h-3.5 w-3.5" />
									</a>
								</Button>
							</TooltipTrigger>
							<TooltipContent>View original</TooltipContent>
						</Tooltip>
					)}
				</div>
			</div>

			{/* Rating */}
			{content.rating && (
				<div className="flex items-center gap-1 mb-2">
					{[1, 2, 3, 4, 5].map((star) => (
						<Star
							key={star}
							className={`h-4 w-4 ${
								star <= Number(content.rating)
									? "fill-yellow-400 text-yellow-400"
									: "text-muted-foreground"
							}`}
						/>
					))}
				</div>
			)}

			{/* Thumbnail / media preview */}
			{thumbnail && (
				<a
					href={mediaUrl || content.source_url || "#"}
					target="_blank"
					rel="noopener noreferrer"
					className="block mb-2"
				>
					<img
						src={thumbnail}
						alt=""
						className={`rounded-md object-cover ${payloadType === "media" ? "max-h-96 w-full" : "max-h-48"}`}
						loading="lazy"
					/>
				</a>
			)}

			{/* Classification evidence excerpt */}
			{content.excerpt && (
				<div className="text-sm italic text-muted-foreground border-l-2 border-primary/40 pl-2 mb-1">
					{content.excerpt}
				</div>
			)}

			{/* Content */}
			{(() => {
				switch (payloadType) {
					case "markdown":
						if (displayText) {
							return (
								<div className="max-w-none text-sm space-y-2">
									<MarkdownText text={displayText} />
								</div>
							);
						}
						break;

					case "json_template": {
						const tmpl = content.payload_template as {
							root: JsonNode;
						} | null;
						if (tmpl?.root) {
							return (
								<JsonRenderer
									template={{ root: tmpl.root }}
									data={(content.payload_data as Record<string, unknown>) || {}}
								/>
							);
						}
						if (displayText) {
							return (
								<div className="text-sm whitespace-pre-wrap">{displayText}</div>
							);
						}
						break;
					}

					case "media":
						return (
							<div className="space-y-3">
								{!thumbnail && mediaUrl && (
									<a
										href={mediaUrl}
										target="_blank"
										rel="noopener noreferrer"
										className="text-sm text-primary hover:underline truncate block"
									>
										{mediaUrl}
									</a>
								)}
								{displayText && (
									<div className="text-sm whitespace-pre-wrap text-muted-foreground">
										{displayText}
									</div>
								)}
							</div>
						);

					case "empty":
						return (
							<div className="space-y-3">
								{metadataEntries.length > 0 ? (
									<dl className="grid gap-x-3 gap-y-2 text-sm sm:grid-cols-[minmax(140px,180px)_1fr]">
										{metadataEntries.map(([key, value]) => (
											<div key={key} className="contents">
												<dt className="text-muted-foreground">
													{sentenceCase(key)}
												</dt>
												<dd className="min-w-0 break-words font-mono text-xs sm:text-sm">
													{renderMetadataValue(value)}
												</dd>
											</div>
										))}
									</dl>
								) : (
									<p className="text-sm text-muted-foreground italic">
										No content
									</p>
								)}
							</div>
						);

					default:
						if (displayText) {
							return (
								<div className="text-sm whitespace-pre-wrap">{displayText}</div>
							);
						}
						break;
				}

				// Fallback: metadata grid + media URL
				return (
					<div className="space-y-3">
						{mediaUrl && !thumbnail && (
							<a
								href={mediaUrl}
								target="_blank"
								rel="noopener noreferrer"
								className="text-sm text-muted-foreground hover:text-foreground truncate block"
							>
								{mediaUrl}
							</a>
						)}
						{metadataEntries.length > 0 && (
							<dl className="grid gap-x-3 gap-y-2 text-sm sm:grid-cols-[minmax(140px,180px)_1fr]">
								{metadataEntries.map(([key, value]) => (
									<div key={key} className="contents">
										<dt className="text-muted-foreground">
											{sentenceCase(key)}
										</dt>
										<dd className="min-w-0 break-words font-mono text-xs sm:text-sm">
											{renderMetadataValue(value)}
										</dd>
									</div>
								))}
							</dl>
						)}
					</div>
				);
			})()}

			{shouldTruncate && (
				<Button
					variant="link"
					size="sm"
					className="px-0 h-6 mt-1"
					onClick={() => setShowFullText(!showFullText)}
				>

