        WHERE iwc.event_id = f.id AND iwc.watcher_id = $1
      )`;

    // unprocessed_count drives the badge ("N pending analysis"). Cap the
    // scan at 1000 rows: the badge shows "1000+" semantics above that, and
    // the cap keeps the page query under the 10s frontend timeout even on
    // entities with 100K+ events in the lookback window. The 90-day bound
    // above lets the planner pick `idx_events_entity_ids_occurred_at`, but
    // on a high-volume entity that index range still has ~78K rows; the
    // LIMIT short-circuits row fetches once we've passed the cap.
    //
    // monthlyContent / monthlyLinked build the per-month histogram for
    // unprocessed_ranges, only used inside the (collapsed-by-default) summary
    // view. Off by default; the summary expand path sets include_pending_ranges
    // to true.
    const UNPROCESSED_COUNT_CAP = 1000;
    const unprocessedCountPromise = sql.unsafe(
      `SELECT CAST(COUNT(*) AS INTEGER) as count FROM (
        SELECT 1
        FROM current_event_records f
        WHERE ${entityScopeCondition}
          ${occurredAtBound ? `AND ${occurredAtBound}` : ''}
          AND ${notInWindowClause}
        LIMIT ${UNPROCESSED_COUNT_CAP}
      ) capped`,
      watcherScopedParams
    );

    const histogramPromise = args.include_pending_ranges
      ? Promise.all([
          sql.unsafe(
            `SELECT DATE_TRUNC('month', f.occurred_at) as month, COUNT(*) as total
              FROM current_event_records f
              WHERE ${entityScopeOnlyCondition}
                ${occurredAtBoundNoWatcher ? `AND ${occurredAtBoundNoWatcher}` : ''}
              GROUP BY DATE_TRUNC('month', f.occurred_at)
              ORDER BY month`,
            noWatcherParams
          ),
          sql.unsafe(
            `SELECT DATE_TRUNC('month', f.occurred_at) as month, COUNT(DISTINCT f.id) as linked
              FROM current_event_records f
              JOIN watcher_window_events iwc ON f.id = iwc.event_id
              WHERE ${entityScopeCondition}
                ${occurredAtBound ? `AND ${occurredAtBound}` : ''}
                AND iwc.watcher_id = $1
              GROUP BY DATE_TRUNC('month', f.occurred_at)`,
            watcherScopedParams
          ),
        ])
      : Promise.resolve([[], []] as [unknown[], unknown[]]);

    const [unprocessedCountResult, [monthlyContentResult, monthlyLinkedResult]] = await Promise.all(
      [unprocessedCountPromise, histogramPromise]
    );

    const unprocessedCount = Number(unprocessedCountResult[0]?.count ?? 0);

    // Calculate next window bounds based on granularity using the
    // already-fetched latestEnd (no extra round-trip).
    let nextWindow: PendingAnalysis['next_window'] = null;

    if (unprocessedCount > 0) {
      const now = new Date();
      let windowStart: Date;
      let windowEnd: Date;

      if (latestStart) {
        // The dispatcher's own rule, called — not reimplemented. `get_behavior`
        // only PREVIEWS what `computePendingWindow` will hand the run, so a
        // second copy here is a second thing to keep in sync, and it already
        // drifted once (preview chained off window_end, dispatcher off
        // window_start — a full period apart on legacy rows).
        windowStart = nextBehaviorWindowStart(new Date(latestStart), now, timeGranularity);
      } else {
        // No windows yet — find the earliest unprocessed event for this
        // entity. Unbounded by occurred_at: pi review (#481) flagged that
        // a 90-day default would silently strip pre-existing backlogs from
        // the next_window calculation when a user creates a watcher on top
        // of long-since-ingested data.
        const earliestResult = await sql.unsafe(
          `SELECT MIN(f.occurred_at) as earliest
            FROM current_event_records f
            WHERE ${entityScopeCondition}
              AND ${notInWindowClause}`,
          [args.behavior_id, ...entityLinkParams]
        );
        const earliest = earliestResult[0]?.earliest as string | null;
        // Aligned too: an arbitrary event timestamp would preview a window
        // starting mid-period, which is not a period the dispatcher can emit.
        windowStart = alignToBehaviorWindowStart(
          earliest ? new Date(earliest) : now,
          timeGranularity
        );
      }

      // A full period, never truncated at `now`. Truncating made the preview
      // disagree with what `computePendingWindow` actually dispatches (it always
      // emits a whole period), and a partial end is not a window any run can be
      // given.
      windowEnd = addBehaviorPeriod(windowStart, timeGranularity);

      nextWindow = {
        start: windowStart.toISOString(),
        end: windowEnd.toISOString(),
        granularity: timeGranularity,
      };
    }

    const unprocessedRanges = args.include_pending_ranges
      ? foldUnprocessedRanges(
          monthlyContentResult as Array<{ month: string; total: number | string }>,
          monthlyLinkedResult as Array<{ month: string; linked: number | string }>,
          false
        )
      : [];

    params.push(...statsVisibility.params);
    paramIndex += statsVisibility.params.length;
  }

  // Stats query WITHOUT classification filters (to show full distribution)
  const statsQueryResult = await sql.unsafe(
    `
    WITH matching_content AS (
      SELECT f.id
      FROM current_event_records f
      LEFT JOIN connections c ON c.id = f.connection_id
      ${windowJoinSql}
      WHERE ${conditions.join(' AND ')}
    ),
    ranked_classifications AS (
      -- P4: dedup per (event, stable classifier_id) directly; version ordering is redundant.
      SELECT
        cc.event_id,
        cc.classifier_id,
        cc."values",
        ROW_NUMBER() OVER (
          PARTITION BY cc.event_id, cc.classifier_id
          ORDER BY
            CASE cc.source WHEN 'user' THEN 1 WHEN 'llm' THEN 2 ELSE 3 END,
            cc.created_at DESC
        ) as rn
      FROM event_classifications cc
      JOIN matching_content mc ON mc.id = cc.event_id
      WHERE cc.classifier_id IS NOT NULL
    ),
    latest_classifications AS (
      SELECT event_id, classifier_id, "values"
      FROM ranked_classifications
      WHERE rn = 1
    )
    SELECT
      fcl.slug as classifier_slug,
      fcl.attribute_key,
      value::text as value,
      COUNT(*) as count
    FROM latest_classifications lc
    JOIN classify_facet fcl ON lc.classifier_id = fcl.id
    CROSS JOIN unnest(lc."values") AS t(value)
    GROUP BY fcl.slug, fcl.attribute_key, value
    ORDER BY fcl.slug, count DESC
  `,
    params
  );

  // Transform to nested object structure: { classifier_slug: { value: count } }
  const classificationStats: NonNullable<GetContentResult['classification_stats']> = {};
  for (const row of statsQueryResult as unknown as ClassificationStatsRow[]) {
    (classificationStats[row.classifier_slug] ??= {})[row.value] = Number(row.count);
  }
  return classificationStats;
}
 */
function buildContentQuery(opts: {
  table: string;
  alias: string;
  /** Extra JOIN clause(s) spliced in before the fixed connection/oauth joins. */
  join?: string;
  where: string;
  orderBy: string;
  limit: number;
  offset: number;
}): string {
  const { table, alias: a, join = '', where, orderBy, limit, offset } = opts;
  return `
    SELECT
      ${a}.id,
      ${a}.entity_ids,
      ${a}.payload_text,
      ${a}.title,
      ${a}.author_name,
      ${a}.source_url,
      ${a}.occurred_at,
      ${a}.semantic_type,
      ${a}.origin_id,
      ${a}.origin_parent_id,
      COALESCE(${a}.origin_parent_id, ${a}.origin_id) as root_origin_id,
      CASE WHEN ${a}.origin_parent_id IS NULL THEN 0 ELSE 1 END as depth,
      ${a}.origin_type,
      ${a}.payload_type,
      ${a}.payload_data,
      ${a}.payload_template,
      ${a}.attachments,
      ${a}.score,
      ${a}.metadata,
      ${a}.created_at,
      COALESCE(${a}.connector_key, c.connector_key) as platform,
      ${a}.interaction_type,
      ${a}.interaction_status,
      ${a}.interaction_input_schema,
      ${a}.interaction_input,
      ${a}.interaction_output,
      ${a}.interaction_error,
      ${a}.supersedes_event_id,
      ${a}.superseded_by,
      ${a}.run_id,
      oc.client_name,
      -- Per-event classifications keyed by classifier attribute, matching the
      -- list/search path shape so exact reads (content_ids / include_superseded)
      -- surface a manual classifiers.classify immediately (#2050). One row per
      -- (event, classifier): source priority user then llm then embedding,
      -- newest first -- the same dedup rule as buildLatestClassificationsCteSql.
      COALESCE(
        (
          SELECT jsonb_object_agg(
            lc.attribute_key,
            jsonb_build_object(
              'values', lc.values,
              'confidences', lc.confidences,
              'source', lc.source,
              'is_manual', lc.is_manual
            )
          )
          FROM (
            SELECT
              fcl.attribute_key,
              cc."values" AS values,
              cc.confidences,
              cc.source,
              cc.is_manual,
              ROW_NUMBER() OVER (
                PARTITION BY cc.event_id, cc.classifier_id
                ORDER BY
                  CASE cc.source WHEN 'user' THEN 1 WHEN 'llm' THEN 2 ELSE 3 END,
                  cc.created_at DESC
              ) AS rn
            FROM event_classifications cc
            JOIN classify_facet fcl ON fcl.id = cc.classifier_id
            WHERE cc.event_id = ${a}.id AND cc.classifier_id IS NOT NULL
          ) lc
          WHERE lc.rn = 1
        ),
        '{}'::jsonb
      ) as classifications
    FROM ${table} ${a}
    ${join}
    LEFT JOIN connections c ON c.id = ${a}.connection_id
    LEFT JOIN oauth_clients oc ON oc.id = ${a}.client_id
    WHERE ${where}
    ORDER BY ${orderBy}
    LIMIT ${limit}
    OFFSET ${offset}
  `;
}

