export const QUERYABLE_TABLE_NAMES = new Set(QUERYABLE_SCHEMA.tables.map((t) => t.name));

/**
 * Exposed relation name → physical table, for the relations whose agent-facing
 * name differs from the engine's.
 *
 * The agent-facing product name is Behavior; `watcher` is internal engine/DB
 * vocabulary that must not reach an agent (AGENTS.md hard invariant). The
 * allowlist error enumerates {@link QUERYABLE_TABLE_NAMES} verbatim to the
 * caller, so exposing the physical names both leaked the vocabulary and told the
 * agent that `behaviors` — the name every other tool uses — does not exist.
 *
 * Only the RELATION is renamed. Column identifiers stay internal
 * (`behavior_versions.watcher_id`, `event_classifications.watcher_id`) because
 * they are the real join keys and renaming them would desync the projection
 * from the physical row.
 *
 * Every entry must be consumed by the CTE builder in `execute-data-sources`;
 * a relation with no physical mapping falls through to the entity-type-slug
 * branch and silently returns entities instead of erroring.
 */
const PHYSICAL_TABLE_BY_RELATION: ReadonlyMap<string, string> = new Map([
  ['behaviors', 'watchers'],
  ['behavior_versions', 'watcher_versions'],
]);

/** Physical table backing an exposed relation (identity when not renamed). */
export function physicalTableFor(relation: string): string {
  return PHYSICAL_TABLE_BY_RELATION.get(relation) ?? relation;
}

/**
 * Queryable tables that stay OWNER/ADMIN-only even when query_sql / metric_series
 * are member-accessible: the auth + identity tables. Members can read the
 * org's operational data (entities, events, connections, feeds, watchers, …) but
 * not enumerate every OAuth token/app or the full user roster. Secret columns
 * (credentials, client_secret, token_hash, email, phone) are excluded from the
 * schema above, and the secret-carrying `config` jsonb is redacted in-place;
 * this is the table-level guard on top of that.
 *
 * Do NOT rely on this set to protect a column: `connections` and `feeds` are
 * intentionally member-readable, so a secret in one of their columns must be
 * excluded or redacted at the schema, not gated here.
 */
export const ADMIN_ONLY_QUERYABLE_TABLES: ReadonlySet<string> = new Set([
  'oauth_tokens',
  'oauth_clients',
  'user',
]);

/** table name → column definitions for use in CTE SELECT.
 *  Columns with `expr` are derived from JSONB and need special handling. */
export const SAFE_COLUMN_DEFS = new Map<string, ColumnDef[]>(
  QUERYABLE_SCHEMA.tables.map((t) => [t.name, t.columns])
);

/** Build a SELECT column list from column defs, optionally prefixed with a table alias. */
export function buildColumnList(
  defs: ColumnDef[],
  alias?: string,
  table?: string
): string {
  return defs
    .map((c) => {
      if (c.expr) {
        // `$COL$` marks every reference to the source column, so an expression
        // may use it more than once (the redaction CASE reads `config` three
        // times). Legacy expressions with no marker keep the old behavior:
        // alias-prefix the leading identifier.
        const ref = alias ? `${alias}."${c.name}"` : `"${c.name}"`;
        let prefixed = c.expr.includes(COLUMN_REF)
          ? c.expr.split(COLUMN_REF).join(ref)
          : alias
            ? c.expr.replace(/^(\w+)/, `${alias}.$1`)
            : c.expr;
        // `$DECLARED$` resolves to the connector's declared secret key set for
        // the row. It needs a table alias to correlate on, and the correlation
        // differs per table: `connections` carries `connector_key` directly,
        // `feeds` reaches the definition through `connection_id`. With no alias
        // — or an unrecognized table — there is nothing to correlate to, so it
        // degrades to the empty set: heuristic-only, never MORE exposed than
        // before, just less precise.
        if (prefixed.includes(DECLARED_SECRETS_REF)) {
          const declared =
            alias && table === 'connections'
              ? declaredSecretKeysExpr(alias)
              : alias && table === 'feeds'
                ? feedDeclaredSecretKeysExpr(alias)
                : `ARRAY[]::text[]`;
          prefixed = prefixed.split(DECLARED_SECRETS_REF).join(declared);
        }
        return `${prefixed} as "${c.name}"`;
      }
      return alias ? `${alias}."${c.name}"` : `"${c.name}"`;
    })
    .join(', ');
}
}

// ============================================
// CTE Building
// ============================================

/**
 * Build org-scoped CTEs for each referenced table and combine with the user query.
 *
 * Core tables get predefined scoping patterns. Unknown table names are
 * treated as entity_type slugs (filtered from the entities table).
 */
export function buildScopedQuery(
  userQuery: string,
  tableRefs: string[],
  context: DataSourceContext,
  options?: { safeColumns?: Map<string, ColumnDef[]> }
): { sql: string; params: unknown[] } {
  const params: unknown[] = [];
  let idx = 0;

  // $1 = organizationId
  idx++;
  params.push(context.organizationId);
  const orgP = `$${idx}`;

  // Per-user connection visibility (S0). Applied to EVERY CTE on this seam that
  // exposes connection-sourced event content — `events`, `event_classifications`
  // (whose `excerpts` is verbatim source text), and `connections` — so query_sql
  // / metrics / client.query never surface another user's private-connection data.
  // This is the same gate search_memory/get_content already enforce. M1 routes
  // both shapes through the one connection-visibility compiler keyed on an
  // AuthzScope; `principal` null (headless/service) yields org-visible-only,
  // fail-closed for private data.
  const scope: AuthzScope = {
    organizationId: context.organizationId,
    principal: context.userId ?? null,
  };

  // For a table holding events (alias has a `connection_id` col): restrict to
  // org-visible connections or the requesting user's own private ones.
  const eventConnVisibility = (alias: string): string => {
    const vis = compileConnectionFkVisibility(scope, idx + 1, alias);
    params.push(...vis.params);
    idx += vis.params.length;
    return ` ${vis.sql}`;
  };

  // Per-resource membership gate for an events table (alias has `entity_ids` +
  // `connection_id`): on ACL-enforced connections, restrict to events linked to a
  // resource the requester is `member_of`. Composed AFTER eventConnVisibility on
  // event-bearing tables ONLY (NOT feeds, which carry no entity_ids).
  const eventResourceVisibility = (alias: string): string => {
    const vis = compileResourceVisibility(scope, idx + 1, alias);
    params.push(...vis.params);
    idx += vis.params.length;
    return ` ${vis.sql}`;
  };

  // Tenancy predicate for an events table (alias has `organization_id`,
  // `entity_ids`, `connection_id`). Mirrors buildOrgScopeWhere in
  // content-search.ts: an event is in scope if it was stamped to the caller's
  // org directly, OR any of its entity_ids belong to the caller's org, OR it
  // came in through a connection in the caller's org.
  //
  // Shared by `events` and `event_classifications` on purpose. These were two
  // hand-written predicates and they drifted: the classifications CTE only ever
  // implemented the middle disjunct (an entity join), so labels on an
  // entity-less event were invisible while the event itself was queryable in
  // the same breath. A classification must be visible exactly when its event
  // is, and one expression is the only way to keep that true.
  //
  // Written as ONE template literal on purpose: `+`-joining SQL fragments trips
  // the check-security-patterns string-concat guard, and this fragment is far
  // enough from the whitelisted for-loop below that no `security-allowed:`
  // annotation covers it. Keep it concat-free rather than allowlisting it.
  const eventOrgScope = (alias: string): string =>
    `(${alias}.organization_id = ${orgP}
      OR EXISTS (SELECT 1 FROM public.entities ent
        WHERE ent.id = ANY(${alias}.entity_ids) AND ent.organization_id = ${orgP})
      OR EXISTS (SELECT 1 FROM public.connections con
        WHERE con.id = ${alias}.connection_id AND con.organization_id = ${orgP}))`;

  // Per-channel membership gate for the `channel_messages` table (alias has
  // `connection_id` + `channel_id`): on an ACL-enforced Slack connection, restrict
  // to channels the requester is `member_of`. A headless/null principal sees only
  // non-enforced channels — this is what keeps a watcher's streaming @feed source
  // from leaking enforced-channel content into the shared recap.
  const channelMessagesVisibility = (alias: string): string => {
    const vis = compileChannelMessagesVisibility(scope, idx + 1, alias);
    params.push(...vis.params);
    idx += vis.params.length;
    return ` ${vis.sql}`;
  };

  // For the `connections` table itself: the row is visible when org-shared or
  // owned by the requesting user (mirrors manage_connections CRUD).
  const connectionRowVisibility = (alias: string): string =>
    ` ${compileConnectionRowVisibility(scope, alias)}`;

  // {{entityId}} substitution — only allocates a param when the query uses it
  let processedQuery = userQuery;
  if (context.entityIds && context.entityIds.length > 0) {
    let entityP: string | undefined;
    processedQuery = processedQuery.replace(/\{\{entityId\}\}/g, () => {
      if (!entityP) {
        idx++;
        params.push(context.entityIds![0]);
        entityP = `$${idx}::bigint`;
      }
      return entityP;
    });
  }

  // Remove {{organizationId}} — scoping is now automatic via CTEs
  processedQuery = processedQuery.replace(/\{\{organizationId\}\}/g, orgP);

  // Substitute {{query.paramName}} with parameterized values (NULL if missing).
  // Cast to ::text so PostgreSQL can determine the type even when the value is NULL.
  processedQuery = processedQuery.replace(/\{\{query\.(\w+)\}\}/g, (_match, paramName: string) => {
    idx++;
    params.push(context.query?.[paramName] ?? null);
    return `$${idx}::text`;
  });

  // Reject any remaining unknown placeholders
  const remaining = processedQuery.match(/\{\{(\w+(?:\.\w+)?)\}\}/g);
  if (remaining) {
    throw new Error(`Unknown context variables: ${remaining.join(', ')}`);
  }

  // Reject user-provided positional parameters (would conflict with ours)
  if (/\$\d+/.test(userQuery)) {
    throw new Error('Positional parameters ($1, $2, ...) are not allowed in data source queries');
  }

  // Build CTEs
  const ctes: string[] = [];

  // When safeColumns is provided, emit explicit column lists instead of SELECT *
  const sc = options?.safeColumns;
  const sel = (table: string, alias?: string) => {
    const defs = sc?.get(table);
    if (!defs) return alias ? `${alias}.*` : '*';
    // `table` drives how a redaction expression resolves the row's
    // connector-DECLARED secret fields: a connection carries `connector_key`,
    // a feed reaches it through `connection_id`.
    return buildColumnList(defs, alias, table);
